/**
 * React component for displaying subtitle text from the remote player
 * @module SubtitleDisplay
 */
import React, { FC, useEffect, useState } from 'react';
import { Card, Text, Stack, Badge, Box } from '@mantine/core';
import { RemotePlayerState, SubtitleTrack, SubtitleCue } from '@/domain/Messages';
import { fetchAndParseVTT, getCueAtTime } from '@/utils/vttParser';

interface SubtitleDisplayProps {
  playerState?: RemotePlayerState;
  availableSubtitleTracks?: SubtitleTrack[];
  currentSubtitleTrack?: number | null;
  showReference?: boolean; // Show reference language side-by-side
  referenceTrackId?: number | null;
  videoUrl?: string; // Base video URL to derive VTT URLs
  scrollMode?: 'follow' | 'scroll';
  scrollIndex?: number;
  scrollCues?: SubtitleCue[];
}

/**
 * Component that displays the current subtitle text and optional reference translation
 * @param {SubtitleDisplayProps} props - Component props
 * @returns {JSX.Element} Rendered subtitle display
 */
export const SubtitleDisplay: FC<SubtitleDisplayProps> = ({
  playerState,
  availableSubtitleTracks = [],
  currentSubtitleTrack = null,
  showReference = false,
  referenceTrackId = null,
  videoUrl,
  scrollMode = 'follow',
  scrollIndex = 0,
  scrollCues = []
}) => {
  const [currentCues, setCurrentCues] = useState<SubtitleCue[]>([]);
  const [referenceCues, setReferenceCues] = useState<SubtitleCue[]>([]);
  const [currentText, setCurrentText] = useState<string>('');
  const [referenceText, setReferenceText] = useState<string>('');

  // Derive VTT URL from video URL and language
  const deriveVttUrl = (baseUrl: string, lang: string): string => {
    const LANG = (lang || '').toUpperCase();
    try {
      const [pathOnly] = baseUrl.split(/[?#]/, 1);
      const dot = pathOnly.lastIndexOf('.');
      const base = dot > -1 ? pathOnly.substring(0, dot) : pathOnly;
      return `${base}-${LANG}.vtt`;
    } catch {
      const dot = baseUrl.lastIndexOf('.');
      const base = dot > -1 ? baseUrl.substring(0, dot) : baseUrl;
      return `${base}-${LANG}.vtt`;
    }
  };

  // Load current subtitle track
  useEffect(() => {
    if (currentSubtitleTrack !== null && availableSubtitleTracks.length > 0 && videoUrl) {
      const track = availableSubtitleTracks.find(t => t.id === currentSubtitleTrack);
      if (track) {
        const url = track.url || deriveVttUrl(videoUrl, track.language);
        fetchAndParseVTT(url).then(setCurrentCues);
      }
    } else {
      setCurrentCues([]);
    }
  }, [currentSubtitleTrack, availableSubtitleTracks, videoUrl]);

  // Load reference subtitle track
  useEffect(() => {
    if (referenceTrackId !== null && availableSubtitleTracks.length > 0 && videoUrl) {
      const track = availableSubtitleTracks.find(t => t.id === referenceTrackId);
      if (track) {
        const url = track.url || deriveVttUrl(videoUrl, track.language);
        fetchAndParseVTT(url).then(setReferenceCues);
      }
    } else {
      setReferenceCues([]);
    }
  }, [referenceTrackId, availableSubtitleTracks, videoUrl]);

  // Update current subtitle text based on playback time or scroll position
  useEffect(() => {
    if (scrollMode === 'scroll' && scrollCues.length > 0) {
      // In scroll mode, show the subtitle at scrollIndex
      setCurrentText(scrollCues[scrollIndex]?.text || '');
    } else if (playerState && currentCues.length > 0) {
      // In follow mode, show subtitle at current time
      const cue = getCueAtTime(currentCues, playerState.currentTime);
      setCurrentText(cue?.text || '');
    } else {
      setCurrentText('');
    }
  }, [playerState?.currentTime, currentCues, scrollMode, scrollIndex, scrollCues]);

  // Update reference subtitle text based on playback time or scroll position
  useEffect(() => {
    if (scrollMode === 'scroll' && scrollCues.length > 0) {
      // In scroll mode, find reference subtitle at same index
      setReferenceText(referenceCues[scrollIndex]?.text || '');
    } else if (playerState && referenceCues.length > 0) {
      // In follow mode, show subtitle at current time
      const cue = getCueAtTime(referenceCues, playerState.currentTime);
      setReferenceText(cue?.text || '');
    } else {
      setReferenceText('');
    }
  }, [playerState?.currentTime, referenceCues, scrollMode, scrollIndex, scrollCues]);

  if (!playerState || currentSubtitleTrack === null) {
    return null;
  }

  const getCurrentTrackInfo = (): SubtitleTrack | undefined => {
    return availableSubtitleTracks.find(
      (track) => track.id === currentSubtitleTrack
    );
  };

  const getReferenceTrackInfo = (): SubtitleTrack | undefined => {
    if (referenceTrackId === null) {
      return undefined;
    }
    return availableSubtitleTracks.find(
      (track) => track.id === referenceTrackId
    );
  };

  const currentTrack = getCurrentTrackInfo();
  const referenceTrack = getReferenceTrackInfo();

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <Card shadow="sm" padding="md" radius="md" withBorder sx={{ minHeight: 150 }}>
      <Stack spacing="sm" sx={{ minHeight: 120 }}>
        {/* Current subtitle track info */}
        <Box sx={{ minHeight: 60 }}>
          {currentTrack && currentText ? (
            <>
              <Badge color="blue" size="sm" mb="xs">
                {currentTrack.label || currentTrack.language}
              </Badge>
              <Text size="md" weight={500}>
                {currentText}
              </Text>
            </>
          ) : (
            <Text size="sm" color="dimmed" align="center" mt="md">
              No subtitles at current time
            </Text>
          )}
        </Box>

        {/* Reference subtitle track (if enabled) */}
        {showReference && (
          <Box sx={{ minHeight: 50 }}>
            {referenceTrack && referenceText ? (
              <>
                <Badge color="gray" size="sm" mb="xs">
                  {referenceTrack.label || referenceTrack.language} (Reference)
                </Badge>
                <Text size="sm" color="dimmed">
                  {referenceText}
                </Text>
              </>
            ) : referenceTrack ? (
              <Text size="xs" color="dimmed" align="center">
                No reference subtitle at current time
              </Text>
            ) : null}
          </Box>
        )}

        {/* Timestamp */}
        <Text size="xs" color="dimmed">
          {formatTime(playerState.currentTime)} / {formatTime(playerState.duration)}
        </Text>
      </Stack>
    </Card>
  );
};
