import { useEffect, useState } from 'react';
import { Stack, Button, Text, Card, Image, Group, SimpleGrid, Loader, Center, ActionIcon } from '@mantine/core';
import { IconDownload } from '@tabler/icons-react';
import { ChildCollection, CollectionDetails, VideoDetails } from '../../domain/Messages';
import { TaskManager } from '@/services/Task';
import { log_error } from '@/services/Logger';
import { showConfirm } from '../Base/Confirm';
import { HTTPRestAdaptor } from '@/adaptors/RestAdaptor';
import { RestAdaptor } from '@/adaptors/Interfaces';


interface DownloadProps {
  host: RestAdaptor;
}

export const Download: React.FC<DownloadProps> = ({ host }) => {
  const [allSeries, setAllSeries] = useState<ChildCollection[]>([]);
  const [activeSeries, setActiveSeries] = useState<CollectionDetails | undefined>(undefined);
  const [currentSeason, setCurrentSeason] = useState<string | undefined>(undefined);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | undefined>(undefined);
  const tv_server = "beta.qcc.cc";

  // Create external host once
  const externalHost = new HTTPRestAdaptor();

  // Fetch all series on component mount
  useEffect(() => {
    fetchSeries();
  }, []);

  const fetchSeries = async () => {
    setLoading(true);
    try {
      const data = await externalHost.get<{ Collection: CollectionDetails }>("media");
      if (data?.Collection?.child_collections) {
        setAllSeries(data.Collection.child_collections);
      }
    } catch (err: any) {
      log_error('Failed to fetch series:', err);
      setError('Failed to fetch series');
    } finally {
      setLoading(false);
    }
  };

  const fetchSeriesDetails = async (seriesPath: string) => {
    setLoading(true);
    try {
      const data = await externalHost.get<{ Collection: CollectionDetails }>(`media/${seriesPath}`);
      if (data?.Collection) {
        setActiveSeries(data.Collection);
        setCurrentSeason(undefined);
      }
    } catch (err: any) {
      log_error('Failed to fetch series details:', err);
      setError('Failed to fetch series details');
    } finally {
      setLoading(false);
    }
  };

  const handleSeriesClick = (series: ChildCollection) => {
    setActiveSeries(undefined);
    fetchSeriesDetails(series.collection);
  };

  const handleSeasonClick = (season: string) => {
    setCurrentSeason(season);
  };

  const handleBackToSeries = () => {
    setActiveSeries(undefined);
    setCurrentSeason(undefined);
  };

  const handleBackToSeasons = () => {
    setCurrentSeason(undefined);
  };

  const confirmMessage = (episodes: VideoDetails[]) => {
    const episode = episodes[0];
    const numEpisodes = episodes.length;
    const episodeTitle = episode.series.episodeTitle || episode.video;
    return (
      <Stack>
        <Text>Download {episodeTitle}{numEpisodes > 1 ? ` and ${numEpisodes} other episodes` : ''}?</Text>
        <Text>This will add it to the download queue.</Text>
      </Stack>
    )
  }

  const handleDownloadEpisode = (episode: VideoDetails) => {
    showConfirm(async () => {
      const downloadManager = new TaskManager(host);
      await downloadManager.download(externalHost, [episode]);
    }, confirmMessage([episode]));
  };

  const handleDownloadSeries = async (seriesTitle: string) => {
    // We'll gather all episodes from all seasons
    if (!activeSeries) return;
    
    // Collect all episodes from all seasons
    const allEpisodes: VideoDetails[] = [];
    for (const seasonKey in activeSeries.series) {
      if (activeSeries.series[seasonKey]?.length > 0) {
        allEpisodes.push(...activeSeries.series[seasonKey]);
      }
    }
    
    if (allEpisodes.length > 0) {
      showConfirm(async () => {
        const taskManager = new TaskManager(host);
        await taskManager.download(externalHost, allEpisodes);
      }, confirmMessage(allEpisodes));
    }
  };

  const handleDownloadSeason = (season: string) => {
    if (!activeSeries || !activeSeries.series[season] || !activeSeries.series[season].length) return;
    
    // Get all episodes in the season
    const episodes = activeSeries.series[season];
    
    if (episodes.length > 0) {
      // First show a confirmation
      const seasonName = season || 'Main';

      showConfirm(async () => {
        const taskManager = new TaskManager(host);
        // Use the new download method to batch download multiple videos
        await taskManager.download(externalHost, episodes);
      }, confirmMessage(episodes));
    }
  };

  // Display loading state
  if (loading) {
    return (
      <Center h={400}>
        <Loader size="xl" />
      </Center>
    );
  }

  // Display error state
  if (error) {
    return (
      <Center h={400}>
        <Text color="red">{error}</Text>
      </Center>
    );
  }

  // Render the list of all series
  const renderSeriesList = () => {
    return (
      <Stack>
        <Text size="xl" fw={700}>Available Series</Text>
        <SimpleGrid cols={3} breakpoints={[
          { maxWidth: 'md', cols: 3 },
          { maxWidth: 'sm', cols: 2 },
          { maxWidth: 'xs', cols: 1 }
        ]} spacing="md">
          {allSeries.map((series) => (
            <Card key={series.collection} shadow="sm" padding="md" radius="md" withBorder>
              {series.thumbnail && series.thumbnail.length > 0 && (
                <Card.Section>
                  <Image 
                  src={thumbnailUrl(series.thumbnail[0])} 
                  height={160} 
                  alt={series.collection} 
                  onClick={() => handleSeriesClick(series)}
                />
                </Card.Section>
              )}
              <Group position="apart" mt="md">
                <Text fw={500} onClick={() => handleSeriesClick(series)} style={{ cursor: 'pointer', flex: 1 }}>
                  {series.collection}
                </Text>
              </Group>
            </Card>
          ))}
        </SimpleGrid>
      </Stack>
    );
  };

  // Render the list of seasons for a series
  const renderSeasonsList = () => {
    if (!activeSeries) return null;
    
    const seasons = Object.keys(activeSeries.series || {}).filter((season) => season !== '');
    // Try to find a thumbnail for the series
    let seriesThumbnail = '';
    for (const seasonKey in activeSeries.series) {
      if (activeSeries.series[seasonKey]?.length > 0 && 
          activeSeries.series[seasonKey][0]?.thumbnail?.length > 0) {
        seriesThumbnail = activeSeries.series[seasonKey][0].thumbnail[0];
        break;
      }
    }

    return (
      <Stack>
        <Group position="apart">
          <Text size="xl" fw={700}>{activeSeries.collection}</Text>
          <Group>
            <ActionIcon 
              color="blue" 
              variant="light"
              onClick={() => handleDownloadSeries(activeSeries.collection)}
            >
              <IconDownload size={18} />
            </ActionIcon>
            <Button variant="subtle" onClick={handleBackToSeries}>Back</Button>
          </Group>
        </Group>
        <SimpleGrid cols={3} breakpoints={[
          { maxWidth: 'md', cols: 3 },
          { maxWidth: 'sm', cols: 2 },
          { maxWidth: 'xs', cols: 1 }
        ]} spacing="md">
          {seasons.map((season) => {
            // Find the first episode in the season to use its thumbnail
            const firstEpisode = activeSeries.series[season]?.[0];
            const thumbnail = firstEpisode?.thumbnail?.length > 0 
              ? firstEpisode.thumbnail[0] 
              : seriesThumbnail;
            
            return (
              <Card key={season} shadow="sm" padding="md" radius="md" withBorder>
                {thumbnail && (
                  <Card.Section>
                    <Image 
                      src={thumbnailUrl(thumbnail)} 
                      height={120} 
                      alt={season} 
                      onClick={() => handleSeasonClick(season)}
                    />
                  </Card.Section>
                )}
                <Group position="apart" mt="md">
                  <Text fw={500} onClick={() => handleSeasonClick(season)} style={{ cursor: 'pointer', flex: 1 }}>
                    {season}
                  </Text>
                  <ActionIcon 
                    color="blue" 
                    variant="light"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDownloadSeason(season);
                    }}
                  >
                    <IconDownload size={18} />
                  </ActionIcon>
                </Group>
              </Card>
            );
          })}
        </SimpleGrid>
      </Stack>
    );
  };

  // Render the list of episodes for a specific season
  const renderEpisodesList = (seasonKey: string) => {
    if (!activeSeries) return null;
    
    const episodes = activeSeries.series[seasonKey] || [];

    return (
      <Stack>
        <Group position="apart">
          <Text size="xl" fw={700}>
            {activeSeries.collection}{seasonKey ? `: ${seasonKey}` : ''}
          </Text>
          <Group>
            <ActionIcon 
              color="blue" 
              variant="light"
              onClick={() => handleDownloadSeries(activeSeries.collection)}
            >
              <IconDownload size={18} />
            </ActionIcon>
            <Button variant="subtle" onClick={currentSeason ? handleBackToSeasons : handleBackToSeries}>Back</Button>
          </Group>
        </Group>
        {episodes.map((episode) => (
          <Card key={episode.checksum} shadow="sm" padding="lg" radius="md" withBorder>
            <Group>
              {episode.thumbnail && episode.thumbnail.length > 0 && (
                <Image 
                  src={thumbnailUrl(episode.thumbnail[0])} 
                  width={120} 
                  height={80}
                  radius="md" 
                  alt={episode.series.episodeTitle || episode.video}
                />
              )}
              <Stack spacing={4} style={{ flex: 1 }}>
                <Text fw={500}>{episode.series.episodeTitle || episode.video}</Text>
                <Text size="sm" color="dimmed">
                  {episode.metadata?.duration ? Math.floor(episode.metadata.duration / 60) + 'm' : ''} 
                  {episode.state === 0 ? ' • Ready to download' : ''}
                </Text>
              </Stack>
              <ActionIcon 
                color="blue" 
                variant="light" 
                size="lg"
                onClick={() => handleDownloadEpisode(episode)}
              >
                <IconDownload size={20} />
              </ActionIcon>
            </Group>
          </Card>
        ))}
      </Stack>
    );
  };

  // Determine which view to render based on state
  if (!activeSeries) {
    return renderSeriesList();
  } else if (!currentSeason) {
    // Check if there are non-empty season names
    const seasons = Object.keys(activeSeries.series || {}).filter(season => season !== '');
    
    // If there are valid seasons, show seasons list
    if (seasons.length > 0) {
      return renderSeasonsList();
    } 
    // If there are episodes with empty season, show them directly
    else if (activeSeries.series[''] && activeSeries.series[''].length > 0) {
      return renderEpisodesList('');
    }
    // Fallback to empty seasons list
    return renderSeasonsList();
  } else {
    return renderEpisodesList(currentSeason);
  }
} 

const thumbnailUrl = (thumbnail: string) => {
  // return `https://${tv_server}/api/thumbnails/${thumbnail}`;
  return thumbnail;
}