import { Player } from "../../services/Player";
import {Image, Stack, Text, Card, RingProgress, Grid, HoverCard, useMantineTheme, createStyles} from "@mantine/core";
import React, {Dispatch, FC, SetStateAction} from "react";
import { VideoDetails} from "../../domain/Messages";
import {VideoDetailsImpl} from "../../domain/Models";
import { getCardSizes, getThumbnail } from "@/domain/Utils";
import { useMediaQuery } from "@mantine/hooks";
import { VideoMenu } from "./VideoMenu";
import { VideoWrapper } from "@/domain/VideoWrapper";
import { getDescription } from "./Utils";

// Create styles using Mantine's createStyles
const useStyles = createStyles((theme) => ({
  title: {
    fontWeight: 500,
    fontSize: theme.fontSizes.lg
  }
}));

interface IVideoCard {
  video: VideoDetails;
  player: Player;
  setDialog: Dispatch<SetStateAction<JSX.Element>>;
  back: (() => void);
}


export const VideoCard: FC<IVideoCard> = ({video, player, setDialog, back }) => {
  const { classes } = useStyles();
  const helper = new VideoWrapper(video);

  const playVideo = (player: Player, video?: VideoDetails) => {
    if (typeof video !== "undefined") {
      player.playVideo(video);
    }
  }

  const description = getDescription(new VideoDetailsImpl(video));
  const theme = useMantineTheme();
  const useSmallImages = useMediaQuery(`(max-width: ${theme.breakpoints.xl})`);
  const dimensions = getCardSizes(useSmallImages);
  const thumbnail = getThumbnail(video.thumbnail, dimensions.imgWidth);

  const image = <Image
      maw={dimensions.imgWidth}
      mx="auto" radius="md" 
      fit="contain"
      src={thumbnail}
      alt={`image from ${helper.name()}`}
    />;

  const playPercentage = helper.getPercentPlayed();
  const ringColour = playPercentage === 100 ? 'green' : 'blue';
  const ringProgress = playPercentage == 0 ? null : <RingProgress
    sx={{zIndex: 100, position: "absolute", top: "10", left: "10"}}
    sections={[
      {value: playPercentage, color: ringColour }, 
    ]}
    size={84}
    label={
      <Text color={ringColour} weight={500} align="center" size="sm">
        {playPercentage}%
      </Text>
    }
  />;

  const title = <HoverCard shadow="md">
      <HoverCard.Target>
        <Text 
          fz="xl" 
          sx={{ cursor: 'pointer' }} 
          onClick={() => playVideo(player, video)} 
        >
          {helper.displayName()}
        </Text>
      </HoverCard.Target>
      <HoverCard.Dropdown>
        { description}
      </HoverCard.Dropdown>
    </HoverCard>;

  const card = (
    <Stack w={dimensions.imgWidth}>
      <Card shadow="sm" padding="lg" radius="md" withBorder>
        <Card.Section 
          sx={{ cursor: 'pointer' }} 
          onClick={() => playVideo(player, video)}
        >
          { ringProgress }
          { image }
        </Card.Section>
        <Card.Section>
          <Grid>
            <Grid.Col h={dimensions.footerHeight} span={12} className={classes.title}>
              { title }
              <VideoMenu setDialog={setDialog} back={back} player={player} helper={helper} />
            </Grid.Col>
          </Grid>
        </Card.Section>
      </Card>
    </Stack>
  );

  return card;
}
