/**
 * Common interface for socket adaptors.
 */
import { RemoteMessage } from "../domain/Messages";

export interface SocketInterface {
  /**
   * Closes the connection.
   */
  close: (code?: number, reason?: string) => void;

  /**
   * Sends a string message.
   */
  send_string: (message: string) => void;

  /**
   * Sends a typed message.
   */
  send: <T>(message: T) => void;

  /**
   * Checks if the connection is ready.
   */
  isReady: () => boolean;

  /**
   * Tries to reconnect.
   */
  retryReconnect: () => void;
  
  /**
   * Checks the connection and sends a ping.
   */
  checkConnection: () => void;
}

/**
 * The type of function callback that executes when a message is received from the server.
 */
export type OnMessageCallback = (message: RemoteMessage) => void;

/**
 * Factory function to create the appropriate socket adaptor based on the environment.
 */
export const createSocketAdaptor = async (
  webSocketFactory: () => WebSocket,
  onMessage: OnMessageCallback,
  channelName?: string
): Promise<SocketInterface> => {
  // Check if we're running in a Tauri environment
  const isTauri = !!(window as any).__TAURI__;
  
  if (isTauri) {
    // Dynamically import the TauriSocketAdaptor to avoid loading it in web contexts
    const { TauriSocketAdaptor } = await import('./TauriSocket');
    return new TauriSocketAdaptor(channelName, onMessage);
  } else {
    // In web context, use the WebSocket adaptor
    const { SocketAdaptor } = await import('./Socket');
    return new SocketAdaptor(webSocketFactory, onMessage);
  }
}; 