/**
 * React component for navigating between subtitles
 * @module SubtitleNavigator
 */
import React, { FC, useState, useEffect } from 'react';
import { Button, Group, Menu, Text, Stack, SegmentedControl } from '@mantine/core';
import {
  IconChevronLeft,
  IconChevronRight,
  IconTextCaption,
  IconChevronDown,
  IconLanguage,
  IconPlayerPlay,
  IconList
} from '@tabler/icons-react';
import { Player } from '@/services/Player';
import { SubtitleTrack, SubtitleCue, RemotePlayerState } from '@/domain/Messages';
import { fetchAndParseVTT, getNextCue, getPreviousCue } from '@/utils/vttParser';

interface SubtitleNavigatorProps {
  player: Player;
  playerState?: RemotePlayerState;
  availableSubtitleTracks?: SubtitleTrack[];
  currentSubtitleTrack?: number | null;
  onSubtitleTrackChange?: (trackId: number | null) => void;
  showReferenceSelector?: boolean;
  currentReferenceTrack?: number | null;
  onReferenceTrackChange?: (trackId: number | null) => void;
  videoUrl?: string;
  onScrollModeChange?: (mode: 'follow' | 'scroll', scrollIndex: number, cues: SubtitleCue[]) => void;
}

const ICON_SIZE = "1.25em";

type NavigationMode = 'follow' | 'scroll';

/**
 * Component that provides subtitle navigation and track selection controls
 * @param {SubtitleNavigatorProps} props - Component props
 * @returns {JSX.Element} Rendered subtitle navigator
 */
export const SubtitleNavigator: FC<SubtitleNavigatorProps> = ({
  player,
  playerState,
  availableSubtitleTracks = [],
  currentSubtitleTrack = null,
  onSubtitleTrackChange,
  showReferenceSelector = false,
  currentReferenceTrack = null,
  onReferenceTrackChange,
  videoUrl,
  onScrollModeChange
}) => {
  const [currentCues, setCurrentCues] = useState<SubtitleCue[]>([]);
  const [navigationMode, setNavigationMode] = useState<NavigationMode>('scroll');
  const [scrollIndex, setScrollIndex] = useState<number>(0);

  // Notify parent of scroll mode changes
  useEffect(() => {
    if (onScrollModeChange) {
      onScrollModeChange(navigationMode, scrollIndex, currentCues);
    }
  }, [navigationMode, scrollIndex, currentCues]);

  // Derive VTT URL from video URL and language
  const deriveVttUrl = (baseUrl: string, lang: string): string => {
    const LANG = (lang || '').toUpperCase();
    try {
      const [pathOnly] = baseUrl.split(/[?#]/, 1);
      const dot = pathOnly.lastIndexOf('.');
      const base = dot > -1 ? pathOnly.substring(0, dot) : pathOnly;
      return `${base}-${LANG}.vtt`;
    } catch {
      const dot = baseUrl.lastIndexOf('.');
      const base = dot > -1 ? baseUrl.substring(0, dot) : baseUrl;
      return `${base}-${LANG}.vtt`;
    }
  };

  // Load current subtitle track cues
  useEffect(() => {
    if (currentSubtitleTrack !== null && availableSubtitleTracks.length > 0 && videoUrl) {
      const track = availableSubtitleTracks.find(t => t.id === currentSubtitleTrack);
      if (track) {
        const url = track.url || deriveVttUrl(videoUrl, track.language);
        fetchAndParseVTT(url).then(cues => {
          setCurrentCues(cues);
          // Initialize scroll position to current playback position
          if (playerState && cues.length > 0) {
            const currentIndex = cues.findIndex(cue =>
              playerState.currentTime >= cue.startTime && playerState.currentTime <= cue.endTime
            );
            if (currentIndex !== -1) {
              setScrollIndex(currentIndex);
            }
          }
        });
      }
    } else {
      setCurrentCues([]);
    }
  }, [currentSubtitleTrack, availableSubtitleTracks, videoUrl]);

  // When switching from follow to scroll mode, sync scroll position with current time
  useEffect(() => {
    if (navigationMode === 'scroll' && playerState && currentCues.length > 0) {
      const currentIndex = currentCues.findIndex(cue =>
        playerState.currentTime >= cue.startTime && playerState.currentTime <= cue.endTime
      );
      if (currentIndex !== -1) {
        setScrollIndex(currentIndex);
      }
    }
  }, [navigationMode]); // Only trigger when mode changes

  const handlePreviousSubtitle = (): void => {
    if (currentCues.length === 0) return;

    if (navigationMode === 'follow' && playerState) {
      // FOLLOW mode: Seek video to previous subtitle
      const previousCue = getPreviousCue(currentCues, playerState.currentTime);
      if (previousCue && previousCue.startTime !== undefined) {
        player.seek(previousCue.startTime - playerState.currentTime);
      }
    } else {
      // SCROLL mode: Just scroll through subtitles without seeking video
      setScrollIndex(prev => Math.max(0, prev - 1));
    }
  };

  const handleNextSubtitle = (): void => {
    if (currentCues.length === 0) return;

    if (navigationMode === 'follow' && playerState) {
      // FOLLOW mode: Seek video to next subtitle
      const nextCue = getNextCue(currentCues, playerState.currentTime);
      if (nextCue && nextCue.startTime !== undefined) {
        player.seek(nextCue.startTime - playerState.currentTime);
      }
    } else {
      // SCROLL mode: Just scroll through subtitles without seeking video
      setScrollIndex(prev => Math.min(currentCues.length - 1, prev + 1));
    }
  };

  const handleSubtitleTrackChange = (trackId: number | null): void => {
    // Send message to remote player to change subtitle track
    if (trackId !== null) {
      player.setSubtitleTrack(trackId);
    }
    // Update local state
    if (onSubtitleTrackChange) {
      onSubtitleTrackChange(trackId);
    }
  };

  const getCurrentTrackLabel = (): string => {
    if (currentSubtitleTrack === null) {
      return 'Off';
    }
    const track = availableSubtitleTracks.find((t) => t.id === currentSubtitleTrack);
    return track?.label || track?.language || 'Unknown';
  };

  const getReferenceTrackLabel = (): string => {
    if (currentReferenceTrack === null) {
      return 'None';
    }
    const track = availableSubtitleTracks.find((t) => t.id === currentReferenceTrack);
    return track?.label || track?.language || 'Unknown';
  };

  return (
    <Stack spacing="sm">
      {/* Mode selector */}
      <Group spacing="xs" position="center">
        <SegmentedControl
          value={navigationMode}
          onChange={(value) => setNavigationMode(value as NavigationMode)}
          data={[
            {
              value: 'scroll',
              label: (
                <Group spacing={5} noWrap>
                  <IconList size={16} />
                  <Text size="sm">Scroll</Text>
                </Group>
              )
            },
            {
              value: 'follow',
              label: (
                <Group spacing={5} noWrap>
                  <IconPlayerPlay size={16} />
                  <Text size="sm">Follow</Text>
                </Group>
              )
            }
          ]}
        />
      </Group>

      {/* Show current scroll position in scroll mode */}
      {navigationMode === 'scroll' && currentCues.length > 0 && currentCues[scrollIndex] && (
        <Text size="xs" color="dimmed" align="center">
          Subtitle {scrollIndex + 1} of {currentCues.length}: {currentCues[scrollIndex].text.substring(0, 50)}...
        </Text>
      )}

      {/* Navigation controls */}
      <Group spacing="xs" position="center">
        <Button
          size="sm"
          variant="filled"
          onClick={handlePreviousSubtitle}
          leftIcon={<IconChevronLeft size={ICON_SIZE} />}
          disabled={currentSubtitleTrack === null}
        >
          Previous
        </Button>
        <Button
          size="sm"
          variant="filled"
          onClick={handleNextSubtitle}
          rightIcon={<IconChevronRight size={ICON_SIZE} />}
          disabled={currentSubtitleTrack === null}
        >
          Next
        </Button>
      </Group>

      {/* Track selectors */}
      {availableSubtitleTracks.length > 0 && (
        <Group spacing="xs" position="center">
          {/* Main subtitle track selector */}
          <Menu shadow="md" width={300}>
            <Menu.Target>
              <Button
                size="sm"
                variant="outline"
                rightIcon={<IconChevronDown size={ICON_SIZE} />}
                leftIcon={<IconTextCaption size={ICON_SIZE} />}
              >
                {getCurrentTrackLabel()}
              </Button>
            </Menu.Target>

            <Menu.Dropdown>
              <Menu.Label>Subtitle Track</Menu.Label>
              <Menu.Item
                onClick={() => handleSubtitleTrackChange(null)}
                sx={{ fontWeight: currentSubtitleTrack === null ? 'bold' : 'normal' }}
              >
                Off
              </Menu.Item>
              <Menu.Divider />
              {availableSubtitleTracks.map((track) => (
                <Menu.Item
                  key={track.id}
                  onClick={() => handleSubtitleTrackChange(track.id)}
                  sx={{ fontWeight: currentSubtitleTrack === track.id ? 'bold' : 'normal' }}
                >
                  {track.label || track.language}
                  {track.language && track.label && ` (${track.language})`}
                </Menu.Item>
              ))}
            </Menu.Dropdown>
          </Menu>

          {/* Reference language selector (optional) */}
          {showReferenceSelector && (
            <Menu shadow="md" width={300}>
              <Menu.Target>
                <Button
                  size="sm"
                  variant="outline"
                  rightIcon={<IconChevronDown size={ICON_SIZE} />}
                  leftIcon={<IconLanguage size={ICON_SIZE} />}
                >
                  Ref: {getReferenceTrackLabel()}
                </Button>
              </Menu.Target>

              <Menu.Dropdown>
                <Menu.Label>Reference Language</Menu.Label>
                <Menu.Item
                  onClick={() => onReferenceTrackChange?.(null)}
                  sx={{ fontWeight: currentReferenceTrack === null ? 'bold' : 'normal' }}
                >
                  None
                </Menu.Item>
                <Menu.Divider />
                {availableSubtitleTracks.map((track) => (
                  <Menu.Item
                    key={track.id}
                    onClick={() => onReferenceTrackChange?.(track.id)}
                    sx={{ fontWeight: currentReferenceTrack === track.id ? 'bold' : 'normal' }}
                  >
                    {track.label || track.language}
                    {track.language && track.label && ` (${track.language})`}
                  </Menu.Item>
                ))}
              </Menu.Dropdown>
            </Menu>
          )}
        </Group>
      )}
    </Stack>
  );
};
