import { configureStore, Middleware } from '@reduxjs/toolkit';

import searchReducer from "./SearchReducer"
import remoteMessageReducer from "./EventReducer"
import seriesReducer from "./SeriesReducer"
import configReducer from "./ConfigReducer"
import videoReducer from "./VideoReducer"
import { socketMiddleware, socketConnect } from "./SocketMiddleware";

// Import adaptors
import { restAdaptor, RestAdaptor } from '@/adaptors';

// Define the type for the thunk extra argument
export interface ThunkExtraArgument {
  restAdaptor: RestAdaptor;
}

// Define the root reducer
const rootReducer = {
    search: searchReducer,
    remote: remoteMessageReducer,
    series: seriesReducer,
  config: configReducer,
  video: videoReducer
};

// Define RootState type based on the reducer structure
export type RootState = {
  search: ReturnType<typeof searchReducer>;
  remote: ReturnType<typeof remoteMessageReducer>;
  series: ReturnType<typeof seriesReducer>;
  config: ReturnType<typeof configReducer>;
  video: ReturnType<typeof videoReducer>;
};

// Create the store
const store = configureStore({
  reducer: rootReducer,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      thunk: {
        extraArgument: { restAdaptor } as ThunkExtraArgument,
      },
      // Configure serialization check to ignore non-serializable adaptor in socket actions
      serializableCheck: {
        ignoredActions: [socketConnect.type],
      },
    }).concat(socketMiddleware() as Middleware)
});

export type AppDispatch = typeof store.dispatch;

export default store;