/**
 * Browser compatibility detection for modern features
 * Particularly useful for smart TVs and other devices with older browsers
 */

// Augment the global Window interface
declare global {
  interface Window {
    hasMantineTransitionSupport?: boolean;
    hasES6Support?: boolean;
    __TAURI__?: object; // Or a more specific type if you know the structure of __TAURI__
    // CSS property is standard, but its 'supports' method might not be on very old browsers
    // However, 'CSS' itself should exist if 'CSS.supports' is being checked.
    // The 'any' cast for CSS.supports might be due to older TS lib versions or extreme legacy.
    // Modern lib.dom.d.ts includes CSS.supports.
  }
}

// Check if transitions are supported by the browser
export const shouldUseTransitions = (): boolean => {
  // Check if we're in a browser
  if (typeof window === 'undefined') return true;
  
  // Check for a flag in localStorage (set by our debug script)
  try {
    if (localStorage.getItem('disableTransitions') === 'true') {
      console.log('Transitions disabled by browser compatibility detection');
      return false;
    }
  } catch (e) {
    // console.warn('Could not access localStorage for transition settings: ', JSON.stringify(e));
    // JSON.stringify(e) can be problematic for Error objects.
    console.warn('Could not access localStorage for transition settings: ', e instanceof Error ? e.message : String(e));
  }
  
  // Firefox is always supported
  if (navigator.userAgent.includes('Firefox/')) {
    console.log('Firefox detected, transitions enabled');
    return true;
  }
  
  // Check if browser is compatible (needs proper ES6 support)
  // Use direct property access now that Window is augmented
  if (typeof window.hasMantineTransitionSupport === 'boolean') {
    if (!window.hasMantineTransitionSupport) {
      console.log('Transitions disabled due to browser incompatibility (hasMantineTransitionSupport flag)');
      return false;
    }
  }
  
  // Check for old Chrome versions specifically
  const chromeVersionMatch = navigator.userAgent.match(/Chrome\/(\d+)/);
  if (chromeVersionMatch && 
      parseInt(chromeVersionMatch[1], 10) < 90 &&
      !navigator.userAgent.includes('Firefox/')) {
    console.log('Transitions disabled due to old Chrome version');
    return false;
  }
  
  return true;
};

// Get browser information for debugging
export const getBrowserInfo = () => {
  if (typeof window === 'undefined') {
    return {
      isServer: true,
      chromeVersion: null,
      firefoxVersion: null, // Added for completeness
      hasMantineTransitionSupport: null,
      hasES6Support: null, // Added for completeness
      isFirefox: false,
    };
  }

  const chromeVersionMatch = navigator.userAgent.match(/Chrome\/(\d+)/);
  const firefoxVersionMatch = navigator.userAgent.match(/Firefox\/(\d+)/);
  
  return {
    isServer: false,
    userAgent: navigator.userAgent,
    chromeVersion: chromeVersionMatch ? parseInt(chromeVersionMatch[1], 10) : null,
    firefoxVersion: firefoxVersionMatch ? parseInt(firefoxVersionMatch[1], 10) : null,
    isFirefox: navigator.userAgent.includes('Firefox/'),
    hasMantineTransitionSupport: typeof window.hasMantineTransitionSupport === 'boolean' ? window.hasMantineTransitionSupport : false,
    hasES6Support: typeof window.hasES6Support === 'boolean' ? window.hasES6Support : false,
  };
};

// Safe alternative to using localStorage directly
export const safeStorage = {
  get: (key: string, defaultValue: string = ''): string => {
    try {
      if (typeof window === 'undefined') return defaultValue;
      const value = localStorage.getItem(key);
      return value === null ? defaultValue : value;
    } catch (e) {
      console.error('Error accessing localStorage:', e);
      return defaultValue;
    }
  },
  set: (key: string, value: string): boolean => {
    try {
      if (typeof window === 'undefined') return false;
      localStorage.setItem(key, value);
      return true;
    } catch (e) {
      console.error('Error writing to localStorage:', e);
      return false;
    }
  }
};

// Get supported CSS features
export const getSupportedCSSFeatures = () => {
  if (typeof window === 'undefined') return { supportsFlexbox: true, supportsGrid: true };
  
  // Check if CSS and CSS.supports are available
  const cssSupports = window.CSS && typeof window.CSS.supports === 'function';
  
  return {
    supportsFlexbox: cssSupports ? window.CSS.supports('display', 'flex') : true, // Default to true if API not present, assuming modern env for this check
    supportsGrid: cssSupports ? window.CSS.supports('display', 'grid') : true,   // Default to true
  };
}; 

export const isMobile = () => {
  return /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
};

export const isTablet = () => {
  return /Tablet|iPad|iPod/i.test(navigator.userAgent);
};

export const isTauri = () => {
  // Access directly now that Window is augmented
  return typeof window.__TAURI__ !== "undefined";
};