import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { PlayRequest } from '@/domain/Messages';
import { videoPlay, videoSeek, videoTogglePause } from './SocketMiddleware';

interface VideoState {
  currentVideo?: PlayRequest;
  isPlaying: boolean;
  isConnected: boolean;
  seekEvent?: number;
}

const initialState: VideoState = {
  currentVideo: undefined,
  isPlaying: false,
  isConnected: false,
  seekEvent: undefined
};

const videoSlice = createSlice({
  name: 'video',
  initialState,
  reducers: {
    setIsConnected: (state, action: PayloadAction<boolean>) => {
      state.isConnected = action.payload;
    },
    clearSeekEvent: (state) => {
      state.seekEvent = undefined;
    }
  },
  extraReducers: (builder) => {
    builder
      .addCase(videoPlay, (state, action) => {
        state.currentVideo = action.payload;
        state.isPlaying = true;
      })
      .addCase(videoTogglePause, (state) => {
        state.isPlaying = !state.isPlaying;
      })
      .addCase(videoSeek, (state, action) => {
        state.seekEvent = action.payload;
      });
  }
});

export const { setIsConnected, clearSeekEvent } = videoSlice.actions;
export default videoSlice.reducer; 