import { PayloadAction, createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import { ChildCollection, CollectionDetails, MediaDetails, VideoDetails, RemotePlayerState, VideoEvent, VideoEventType } from "../Messages";
import { ThunkExtraArgument } from "."; // Import the extra argument type

export interface SeriesState {
  allSeries?: ChildCollection[];
  activeSeries?: CollectionDetails;
  currentSeason?: string;
  currentEpisode?: string;
  playing?: VideoDetails;
  error?: string;
  loadingResults: boolean;
  loadingPlaying: boolean;
}

const initialState: SeriesState = {
  loadingResults: false,
  loadingPlaying: false
};

// Updated fetchSeriesDetails to use the injected RestAdaptor
export const fetchSeriesDetails = createAsyncThunk<
  MediaDetails, // Return type
  string, // Argument type (series path)
  { extra: ThunkExtraArgument; rejectValue: string } // ThunkAPI config
>(
  'series/fetchSeriesDetails',
  async (seriesPath, { extra, rejectWithValue }) => {
    try {
      const query = seriesPath ? `media/${seriesPath}` : "media";
      // Use the adaptor from extraArgument
      const data = await extra.restAdaptor.get<MediaDetails>(query);
      // Assuming the adaptor's get method throws on error or returns a structure
      // that indicates success/failure. If it mimics fetch exactly and needs
      // status checking, that logic would go here.
      return data;
    } catch (error) {
      console.error("Failed to fetch series details:", error);
      return rejectWithValue('Failed to fetch series details');
    }
  }
);

// Updated fetchVideoDetails to use the injected RestAdaptor
export const fetchVideoDetails = createAsyncThunk<
  VideoDetails, // Return type
  string, // Argument type (videoId, assuming it's part of the path)
  { extra: ThunkExtraArgument; rejectValue: string } // ThunkAPI config
>(
  'series/fetchVideoDetails',
  async (videoIdPath, { extra, rejectWithValue }) => {
    try {
      // Construct the path. Ensure videoIdPath is just the ID or the full path segment.
      const query = `media/${videoIdPath}`; // Adapt if videoIdPath needs processing
      // Use the adaptor from extraArgument
      const data = await extra.restAdaptor.get<MediaDetails>(query); // Assuming endpoint returns MediaDetails

      // Check if the response structure is as expected and extract the video
      if (data?.Collection?.videos && data.Collection.videos.length > 0 && data.Collection.videos[0]?.Video) {
         return data.Collection.videos[0].Video;
      } else {
        // Log the structure if it's unexpected
        console.warn('Unexpected response structure for video details:', data);
        throw new Error('Video details not found in response structure');
      }

    } catch (error) {
      console.error("Failed to fetch video details:", error);
      return rejectWithValue('Failed to fetch video details');
    }
  }
);

export const seriesSlice = createSlice({
  name: 'series',
  initialState,
  reducers: {
    setCurrentSeason: (state, action: PayloadAction<string | undefined>) => {
      state.currentSeason = action.payload;
    },
    setCurrentEpisode: (state, action: PayloadAction<string | undefined>) => {
      state.currentEpisode = action.payload;
    },
    setPlaying: (state, action: PayloadAction<VideoDetails | undefined>) => {
      state.playing = action.payload;
    },
    setError: (state, action: PayloadAction<string | undefined>) => {
      state.error = action.payload;
    },
    updateActiveSeriesFromPlayerState: (state, action: PayloadAction<RemotePlayerState>) => {
      const { videoId, currentTime } = action.payload;
      if (state.activeSeries) {
        // Check in videos array
        const videoIndex = state.activeSeries.videos.findIndex(v => v.Video?.checksum === videoId);
        if (videoIndex !== -1 && state.activeSeries.videos[videoIndex].Video) {
          state.activeSeries.videos[videoIndex].Video.playFrom = currentTime;
        }

        // Check in series object
        for (const season in state.activeSeries.series) {
          const episodeIndex = state.activeSeries.series[season].findIndex(v => v.checksum === videoId);
          if (episodeIndex !== -1) {
            state.activeSeries.series[season][episodeIndex].playFrom = currentTime;
          }
        }
      }
    },
    updateFromVideoEvent: (state, action: PayloadAction<VideoEvent[]>) => {
      handleVideoEvent(state, action);
    },
  },
  extraReducers: (builder) => {
    builder.addCase(fetchSeriesDetails.pending, (state) => {
      state.loadingResults = true;
      //state.currentEpisode = undefined;
      //state.currentSeason = undefined;
      //state.activeSeries = undefined;
    });
    builder.addCase(fetchSeriesDetails.fulfilled, (state, action) => {
      const details = action.payload; // Type is already MediaDetails
      state.activeSeries = details.Collection;
      state.error = details.Error;
      if (details.Collection?.collection === "") {
        state.allSeries = details.Collection.child_collections;
      }
      state.loadingResults = false;
    });
    builder.addCase(fetchSeriesDetails.rejected, (state, action) => {
      state.error = action.payload;
      state.loadingResults = false;
    });
    builder.addCase(fetchVideoDetails.pending, (state) => {
      state.loadingPlaying = true;
    });
    builder.addCase(fetchVideoDetails.fulfilled, (state, action) => {
      const details = action.payload; // Type is already VideoDetails
      state.playing = details;
      state.loadingPlaying = false;
    });
    builder.addCase(fetchVideoDetails.rejected, (state, action) => {
      state.error = action.payload as string;
      state.loadingPlaying = false;
    });
  },
});


const handleVideoEvent = (state: SeriesState, action: PayloadAction<VideoEvent[]>) => {

  for (const videoEvent of action.payload) {
    const messageType = videoEvent.type;
    const video = videoEvent.video;
    const checksum = videoEvent.checksum;

    if (state.allSeries && video !== undefined) {
      const seriesTitle = video.series.seriesTitle;
      const seriesIndex = state.allSeries.findIndex(s => s.collection === seriesTitle);
      if (seriesIndex === -1) {
        state.allSeries.push({
          collection: seriesTitle,
          thumbnail: video.thumbnail
        });
        state.allSeries.sort((a, b) => a.collection.localeCompare(b.collection));
      }
    }

    if (!state.activeSeries) {
      continue;
    }

    const videoIndex = state.activeSeries.videos.findIndex(v => v.Video?.checksum === checksum);

    if (messageType === VideoEventType.VideoDeleted) {
      if (videoIndex !== -1) {
        state.activeSeries.videos.splice(videoIndex, 1);
      }
      for (const season in state.activeSeries.series) {
        const episodeIndex = state.activeSeries.series[season].findIndex(v => v.checksum === videoEvent.checksum);
        if (episodeIndex !== -1) {
          state.activeSeries.series[season].splice(episodeIndex, 1);
        }
      }
    }
    else if (messageType === VideoEventType.VideoAdded) {
      if (video?.series.seriesTitle !== state.activeSeries?.collection) {
        continue;
      }
      state.activeSeries.videos.push({ Video: video });
      for (const season in state.activeSeries.series) {
        if (season !== video?.series.season) {
          continue;
        }
        state.activeSeries.series[season].push(video);
      }
    }
    else if (messageType === VideoEventType.VideoChanged) {
      if (videoIndex !== -1 && video) {
        state.activeSeries.videos[videoIndex].Video = video;
      }
      for (const season in state.activeSeries.series) {
        if (season !== video?.series.season) {
          continue;
        }
        const episodeIndex = state.activeSeries.series[season].findIndex(v => v.checksum === videoEvent.checksum);
        if (episodeIndex !== -1) {
          state.activeSeries.series[season][episodeIndex] = video;
        }
      }
    }
  }
}

export const { setCurrentEpisode, setCurrentSeason, setPlaying, setError, updateActiveSeriesFromPlayerState, updateFromVideoEvent } = seriesSlice.actions;

export default seriesSlice.reducer;
