import { ChildCollection, VideoDetails } from "@/domain/Messages";
import { Player } from "@/services/Player";
import { Title, useMantineTheme } from "@mantine/core";
import { FC, useCallback, useEffect, useRef, useState } from "react";
import { Carousel, Embla } from '@mantine/carousel';
import { CollectionCard } from "./CollectionCard";
import { AppDispatch, RootState } from "@/domain/Store";
import { useDispatch, useSelector } from "react-redux";
import { fetchSeriesDetails, setCurrentSeason } from "@/domain/Store/SeriesReducer";
import { getCardSizes, getCollectionsAndVideos } from "@/domain/Utils";
import { useMediaQuery } from "@mantine/hooks";
import { VideoCard } from "./VideoCard";
import useWheelEvents from "@/hooks/wheelEventsHook";


interface IVideoCarouselProps {
  videoPlayer: Player;
}

export const VideoCarousel: FC<IVideoCarouselProps> = ({ videoPlayer }) => {
  const [dialog, setDialog] = useState<JSX.Element>((<></>));
  const dispatch: AppDispatch = useDispatch();
  const activeSeries = useSelector((state: RootState) => state.series.activeSeries);
  const currentSeason = useSelector((state: RootState) => state.series.currentSeason);  
  const theme = useMantineTheme();
  const useSmallImages = useMediaQuery(`(max-width: ${theme.breakpoints.xl})`);
  const dimensions = getCardSizes(useSmallImages);
  const [emblaApi, setEmbla] = useState<Embla | null>(null);
  const { wheel } = useWheelEvents();
  const prevWheelRef = useRef(0);
  const prevDirectionRef = useRef(0);

  /*const scrollCarousel = useCallback((deltaY: number) => {
    if (!emblaApi) return;
  
    const currentIndex = emblaApi.selectedScrollSnap();
    const scrollProgress = emblaApi.scrollProgress();
    
    // Adjust this value to change scroll sensitivity
    const scrollFactor = 0.01;
    
    const newProgress = scrollProgress + (deltaY * scrollFactor);
    const newIndex = Math.round(newProgress * (emblaApi.scrollSnapList().length - 1));
    
    emblaApi.scrollTo(newIndex);
  }, [emblaApi]);*/

  const scrollCarousel = useCallback((deltaY: number) => {
    if (!emblaApi) return;

    const scaler = 0.005;

    const diff = (
      deltaY > prevWheelRef.current ? 
      Math.floor((deltaY - prevWheelRef.current) * scaler) :
      Math.ceil((deltaY - prevWheelRef.current) * scaler)
    );

    console.log(`deltaY: ${deltaY}, prevWheelRef: ${prevWheelRef.current}, diff: ${diff}`);

    if (diff > 0) {
      emblaApi.scrollNext();
    } else if (diff < 0) {
      emblaApi.scrollPrev();
    }

    const direction = deltaY > 0 ? 1 : -1;
    if (prevDirectionRef.current && direction !== prevDirectionRef.current) {
      prevWheelRef.current = deltaY;
    } else if (diff !== 0) { 
      prevWheelRef.current = deltaY;
    } else {
      prevWheelRef.current += deltaY;
    }

    prevDirectionRef.current = direction;

  }, [emblaApi]);

  useEffect(() => {
    scrollCarousel(wheel);
  }, [wheel, scrollCarousel]);

  if (typeof activeSeries === "undefined") {
    return <Title>Loading</Title>
  }

  const { child_collections, videos } = getCollectionsAndVideos(activeSeries, currentSeason);

  const onCollectionClick = (item: string) => {
    if (activeSeries.collection === "") {
      dispatch(fetchSeriesDetails(item));
    } else {
      dispatch(setCurrentSeason(item));
    }
  }  

  const collection_items = child_collections.map((childCollection: ChildCollection): JSX.Element => {
    return (
      <Carousel.Slide key={`collection-${childCollection.collection}`} mb={128}>
        <CollectionCard
          key={`collection-${childCollection.collection}`}
          collection={childCollection}
          onClick={onCollectionClick}
        />
      </Carousel.Slide>
    );
  });

  const video_items = videos.map((video: VideoDetails, index: number): JSX.Element | null => {
    return (
      <Carousel.Slide key={`video-${index}`} mb={128}>
        <VideoCard
          setDialog={setDialog}
          back={() => setDialog((<></>))}
          player={videoPlayer}
          video={video}
        />
      </Carousel.Slide>
    );
  });

  return (
    <>
      <Carousel 
        height={dimensions.imgHeight + dimensions.footerHeight + 128}
        slideGap="lg" 
        align="center"
        controlsOffset="lg" 
        controlSize={120} 
        slideSize={dimensions.imgWidth}
        slidesToScroll="auto"
        withIndicators
        bg="transparent"
        getEmblaApi={setEmbla}
        loop
      >
        {collection_items}
        {video_items}
      </Carousel>
      {dialog}
    </>
  );
}
