/**
 * Typescript module that exports two React components VideoModal and ConvertModal
 * @module Modals
 */
import React, { FC, useEffect, useState } from "react";
import { showWarningAlert } from "../Base/Alert";
import { Button, Group, Radio, Stack, Text, TextInput, Grid, Badge, Table, Divider, Title } from "@mantine/core";
import { Modal } from "@mantine/core";
import { Player } from "../../services/Player";
import { Conversion, VideoMetadata } from "../../domain/Messages";
import { log_error } from "../../services/Logger";

/**
 * Interface representing Mouse Button Event of HTML Button Element
 * @interface MouseButtonEvent
 */
interface MouseButtonEvent extends React.MouseEvent<HTMLButtonElement, MouseEvent> { }

/**
 * Interface representing Radio Input Change Event
 * @interface RadioEvent
 */
interface RadioEvent extends React.ChangeEvent<HTMLInputElement> { }

/**
 * Interface representing Video Modal Props object
 * @interface VideoModalProps
 * @property {Function} onClose - Function that is triggered when the modal is closed
 * @property {String} video - The video string
 * @property {Object} player - Instance of Player class
 */
interface VideoModalProps {
  onClose: () => void;
  video: string;
  videoId: string;
  player: Player;
}

/**
 * React component that renders a modal for renaming a video
 * @function Modals
 * @param {Object} props - The props object
 * @returns {JSX.Element} Rendered component
 */
export const Modals:FC<VideoModalProps> = ({video, videoId, player, onClose}): JSX.Element => {
  const [newName, setNewName] = useState('');

  /**
   * A function that is triggered when the rename button is clicked
   * @async
   * @function renameVideo
   * @param {MouseButtonEvent} e - The event object
   * @returns {Void} Returns nothing
   */
  const renameVideo = async (e: MouseButtonEvent): Promise<void> => {
    e.preventDefault();

    if (newName === "") {
      showWarningAlert("Must enter a new name");
      return;
    }

    onClose();

    await player.renameVideo(videoId, video, newName);
  }

  return (
    <Modal opened={true} onClose={onClose}>
      <Stack>
        {/* Field to enter new name for the video */}
        <TextInput
          id="newName"
          label="New Name"
          placeholder={video}
          value={newName}
          onChange={e => setNewName(e.target.value)}
          required={true}
          withAsterisk
        />
        
        {/* Buttons for Ok and Cancel */}
        <Group position="center">
          <Button onClick={(e) => renameVideo(e)}>OK</Button>
          <Button onClick={onClose} variant="outline">Cancel</Button>
        </Group>
      </Stack>
    </Modal>
  )
}

/**
 * React component that renders a modal for selecting a conversion method for the video
 * @function ConvertModal
 * @param {Object} props - The props object
 * @returns {JSX.Element} Rendered component
 */
export const ConvertModal:FC<VideoModalProps> = ({video, videoId, player, onClose}): JSX.Element => {
  const [conversion, setConversion] = useState('');
  const [availableConversions, setAvailableConversions] = useState<Conversion[]>([]);

  /**
   * A function that is triggered when the component mounts, it fetches the available conversion methods
   * @async
   * @function useEffect
   * @returns {Void} Returns nothing
   */
  useEffect(() => {
    const getConversions = async () => {
      const items = await player.getAvailableConversions();

      // When available conversions are fetched, set the first conversion method as the default conversion method for the video
      if (items.length > 0) {
        setConversion(items[0].name);
      }

      return setAvailableConversions(items);
    }

    // Fetch the available conversions
    getConversions().catch((e) => log_error(e, "getConversions"));

  }, [player]);

  /**
   * A function that is triggered when the convert button is clicked
   * @async
   * @function convertVideo
   * @returns {Void} Returns nothing
   */
  const convertVideo = async (): Promise<void> => {
    if (conversion === "") {
      showWarningAlert("Select a conversion method");
      return;
    }

    onClose();

    await player.convertVideo(videoId, video, conversion);
  }

  /**
   * A function that is triggered when a radio input is clicked to select the conversion method
   * @function onConversionSelect
   * @param {RadioEvent} e - The event object
   * @returns {Void} Returns nothing
   */
  const onConversionSelect = (e: RadioEvent): void => {
    const target = e.currentTarget;
    setConversion(target.value);
  }

  // Create a list of radio inputs to display the available conversion methods
  const conversionsList = availableConversions.map((item: Conversion, index: number): JSX.Element => {
    return (
        <Radio
          key={index}
          id={item.name}
          label={item.name}
          name="conversion"
          value={item.name}
          defaultChecked={index === 0}
          onChange={onConversionSelect}
        />
    )
  });

  return (
    <Modal opened={true} onClose={onClose}>
      <Stack>
        <Text>Convert {video}</Text>
        {conversionsList}
        {/* Buttons for Ok and Cancel */}
        <Group position="center">
          <Button onClick={() => convertVideo()}>OK</Button>
          <Button onClick={onClose} variant="outline">Cancel</Button>
        </Group>
      </Stack>
    </Modal>
  )
}

/**
 * Interface representing Video Metadata Modal Props object
 * @interface VideoMetadataModalProps
 * @property {Function} onClose - Function that is triggered when the modal is closed
 * @property {String} video - The video name
 * @property {VideoMetadata} metadata - The video metadata object
 */
interface VideoMetadataModalProps {
  onClose: () => void;
  video: string;
  metadata: VideoMetadata;
}

/**
 * Helper function to format duration in seconds to HH:MM:SS format
 * @function formatDuration
 * @param {number} seconds - Duration in seconds
 * @returns {string} Formatted duration string
 */
const formatDuration = (seconds: number): string => {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);
  
  if (hours > 0) {
    return `${hours}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }
  return `${minutes}:${secs.toString().padStart(2, '0')}`;
};

/**
 * Helper function to calculate aspect ratio
 * @function calculateAspectRatio
 * @param {number} width - Video width
 * @param {number} height - Video height
 * @returns {string} Aspect ratio string
 */
const calculateAspectRatio = (width: number, height: number): string => {
  if (width === 0 || height === 0) return "Unknown";
  
  const gcd = (a: number, b: number): number => b === 0 ? a : gcd(b, a % b);
  const divisor = gcd(width, height);
  const ratioWidth = width / divisor;
  const ratioHeight = height / divisor;
  
  return `${ratioWidth}:${ratioHeight}`;
};

/**
 * React component that renders a modal for displaying video metadata
 * @function VideoMetadataModal
 * @param {Object} props - The props object
 * @returns {JSX.Element} Rendered component
 */
export const VideoMetadataModal: FC<VideoMetadataModalProps> = ({ video, metadata, onClose }): JSX.Element => {
  const formatValue = (value: any, fallback: string = "N/A"): string => {
    return value !== undefined && value !== null && value !== "" ? value.toString() : fallback;
  };

  return (
    <Modal 
      opened={true} 
      onClose={onClose}
      title={`Video Information - ${video}`}
      size="lg"
    >
      <Stack spacing="md">
        {/* Basic Information Section */}
        <div>
          <Title order={4} mb="sm">Basic Information</Title>
          <Grid>
            <Grid.Col span={6}>
              <Text size="sm" weight={500}>Duration:</Text>
              <Text size="sm">{formatDuration(metadata.duration)}</Text>
            </Grid.Col>
            <Grid.Col span={6}>
              <Text size="sm" weight={500}>Resolution:</Text>
              <Text size="sm">{formatValue(`${metadata.width}x${metadata.height}`)}</Text>
            </Grid.Col>
            <Grid.Col span={6}>
              <Text size="sm" weight={500}>Aspect Ratio:</Text>
              <Text size="sm">{calculateAspectRatio(metadata.aspectWidth, metadata.aspectHeight)}</Text>
            </Grid.Col>
            <Grid.Col span={6}>
              <Text size="sm" weight={500}>Audio Tracks:</Text>
              <Badge color="blue" variant="light">{metadata.audioTracks}</Badge>
            </Grid.Col>
          </Grid>
        </div>

        <Divider />

        {/* Audio Tracks Section */}
        {metadata.audioTrackList && metadata.audioTrackList.length > 0 && (
          <div>
            <Title order={4} mb="sm">Audio Tracks</Title>
            <Table striped highlightOnHover>
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Language</th>
                  <th>Title</th>
                  <th>Codec</th>
                </tr>
              </thead>
              <tbody>
                {metadata.audioTrackList.map((track, index) => (
                  <tr key={index}>
                    <td>{track.id}</td>
                    <td>
                      <Badge color="green" variant="light" size="sm">
                        {formatValue(track.language)}
                      </Badge>
                    </td>
                    <td>{formatValue(track.label)}</td>
                    <td>{formatValue(track.codec)}</td>
                  </tr>
                ))}
              </tbody>
            </Table>
          </div>
        )}

        {/* Subtitle Tracks Section */}
        {metadata.subtitleTracks && metadata.subtitleTracks.length > 0 && (
          <div>
            <Title order={4} mb="sm">Subtitle Tracks</Title>
            <Table striped highlightOnHover>
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Language</th>
                  <th>Title</th>
                </tr>
              </thead>
              <tbody>
                {metadata.subtitleTracks.map((track, index) => (
                  <tr key={index}>
                    <td>{track.id}</td>
                    <td>
                      <Badge color="orange" variant="light" size="sm">
                        {formatValue(track.language)}
                      </Badge>
                    </td>
                    <td>{formatValue(track.label)}</td>
                  </tr>
                ))}
              </tbody>
            </Table>
          </div>
        )}

        {/* Close Button */}
        <Group position="center" mt="md">
          <Button onClick={onClose} variant="outline">Close</Button>
        </Group>
      </Stack>
    </Modal>
  );
};