import { FC } from "react";
import { Affix, rem } from "@mantine/core";
import {VideoPlayer} from "@/services/Player";
import { BackButton } from "../Video/BackButton";
import { DisplaySelector } from "../Video/DisplaySelector";
import VideoSelection from "../Video/VideoSelection";
import {VideoDetails} from "../../domain/Messages";

type PickerProps = {
  videoPlayer: VideoPlayer;
  togglePause?: () => void;
  visible: boolean;
}

export const Picker: FC<PickerProps> = ({ videoPlayer, togglePause, visible }) => {
  const showVideoDetails = (video: VideoDetails) => {
    console.log(`video: ${video.video}`);
    videoPlayer.playVideo(video);
  }

  const tryTogglePause = () => {
    if (typeof(togglePause) !== "undefined") {
      togglePause();
    }
  }

  const bgColor = 'transparent';
  //const bgColor = 'rgba(0, 0, 0.5, 0.5)';

  return (
      <Affix 
        position={{ top: rem(50), left: '10%', bottom: rem(50) }}
        sx={{ 
          transform: `translateX(${visible ? '-5%' : '-200%'})`,
          transition: 'transform 0.3s ease-out',
        }}
      >
        <div 
          style={{ 
            maxHeight: window.innerHeight * 0.85, 
            overflowY: "auto", 
            backgroundColor: bgColor 
          }}>
          <Affix 
            key="backbutton" 
            position={{ top: rem(100), left: rem(20) }}
            sx={{
              opacity: visible ? 1 : 0,
              transition: 'opacity 0.3s ease-out',
              pointerEvents: visible ? 'auto' : 'none'
            }}
          >
            <BackButton size="xl"/>
          </Affix>
          <Affix 
            key="displayselector" 
            position={{ top: rem(100), right: rem(20) }}
            sx={{
              opacity: visible ? 1 : 0,
              transition: 'opacity 0.3s ease-out',
              pointerEvents: visible ? 'auto' : 'none'
            }}
          >
            <DisplaySelector />
          </Affix>
          <VideoSelection 
            videoPlayer={videoPlayer} 
            isActive={visible} 
            showVideoDetails={showVideoDetails}
          />
        </div>
      </Affix>
  );
}