import { getCollectionsAndVideos } from "@/domain/Utils";
import { ChildCollection, VideoDetails} from "../../domain/Messages";
import { VideoItem} from "./VideoItem";
import { List } from "@mantine/core";
import { AppDispatch, RootState } from "@/domain/Store";
import { useDispatch, useSelector } from "react-redux";
import { fetchSeriesDetails, setCurrentSeason } from "@/domain/Store/SeriesReducer";
import { FC } from "react";
import { CollectionItem } from "./CollectionItem";
import { Player } from "@/services/Player";


interface IVideoEntryList {
  videoPlayer: Player;
  showVideoDetails?: (video: VideoDetails) => void;
}

/**
 * VideoList component, used to display a list of videos and child collections
 * 
 * @param {IVideoEntryList} message - object containing the current message entry, collection set function and player
 * 
 * @returns {JSX.Element} - returns a JSX element containing the video and collection items to be displayed
 */
export const VideoList: FC<IVideoEntryList> = ({videoPlayer: player, showVideoDetails}): JSX.Element => {
  const dispatch: AppDispatch = useDispatch();
  const activeSeries = useSelector((state: RootState) => state.series.activeSeries);
  const currentSeason = useSelector((state: RootState) => state.series.currentSeason);

  if (!activeSeries) {
    return <>Nothing to watch - download some videos</>;
  }

  const { child_collections, videos } = getCollectionsAndVideos(activeSeries, currentSeason);
  const lastCollection = child_collections.length - 1;
  const lastVideo = videos.length - 1;

  const onCollectionClick = (item: string) => {
    if (activeSeries.collection === "") {
      dispatch(fetchSeriesDetails(item));
    } else {
      dispatch(setCurrentSeason(item));
    }
  }

  const collection_items = child_collections.map((childCollection: ChildCollection, index: number): JSX.Element => {
    return (
      <CollectionItem
        key={childCollection.collection}
        isLast={index === lastCollection && lastVideo < 0}
        name={childCollection.collection}
        collection={activeSeries.collection}
        onClick={() => onCollectionClick(childCollection.collection)}
        player={player}
      />
    );
  });

  const video_items = videos.map((video: VideoDetails, index: number): JSX.Element | null => {
    return (
      <VideoItem
        key={index}
        video={video}
        showVideoDetails={showVideoDetails}
      />
    );
  });

  return (
    <List listStyleType="none">
      {collection_items}
      {video_items}     
    </List>
  );
}
