/**
 * Utility for parsing WebVTT subtitle files
 * @module vttParser
 */

import { SubtitleCue } from '@/domain/Messages';

/**
 * Parse a VTT timestamp string (e.g., "00:01:23.456") to seconds
 * @param timestamp - VTT timestamp string
 * @returns Time in seconds
 */
function parseTimestamp(timestamp: string): number {
  const parts = timestamp.split(':');
  let hours = 0;
  let minutes = 0;
  let seconds = 0;

  if (parts.length === 3) {
    // HH:MM:SS.mmm format
    hours = parseInt(parts[0], 10);
    minutes = parseInt(parts[1], 10);
    seconds = parseFloat(parts[2]);
  } else if (parts.length === 2) {
    // MM:SS.mmm format
    minutes = parseInt(parts[0], 10);
    seconds = parseFloat(parts[1]);
  }

  return hours * 3600 + minutes * 60 + seconds;
}

/**
 * Parse a VTT file content into an array of SubtitleCue objects
 * @param vttContent - Raw VTT file content as string
 * @returns Array of parsed subtitle cues
 */
export function parseVTT(vttContent: string): SubtitleCue[] {
  const cues: SubtitleCue[] = [];

  // Split into lines and remove empty lines
  const lines = vttContent.split('\n').map(line => line.trim());

  let i = 0;

  // Skip header (WEBVTT line and any headers)
  while (i < lines.length && !lines[i].includes('-->')) {
    i++;
  }

  // Parse cues
  while (i < lines.length) {
    const line = lines[i];

    // Check if this is a timestamp line
    if (line.includes('-->')) {
      const [startStr, endStr] = line.split('-->').map(s => s.trim());
      const startTime = parseTimestamp(startStr);
      const endTime = parseTimestamp(endStr);

      // Collect all text lines until next empty line or timestamp
      i++;
      const textLines: string[] = [];
      while (i < lines.length && lines[i] && !lines[i].includes('-->')) {
        // Skip cue identifiers (numeric lines before timestamps)
        if (!/^\d+$/.test(lines[i])) {
          textLines.push(lines[i]);
        }
        i++;
      }

      if (textLines.length > 0) {
        cues.push({
          startTime,
          endTime,
          text: textLines.join('\n')
        });
      }
    } else {
      i++;
    }
  }

  return cues;
}

/**
 * Fetch and parse a VTT file from a URL
 * @param url - URL to the VTT file
 * @returns Promise resolving to array of parsed subtitle cues
 */
export async function fetchAndParseVTT(url: string): Promise<SubtitleCue[]> {
  try {
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`Failed to fetch VTT file: ${response.statusText}`);
    }
    const content = await response.text();
    return parseVTT(content);
  } catch (error) {
    console.error('Error fetching VTT file:', error);
    return [];
  }
}

/**
 * Find the subtitle cue at a specific time
 * @param cues - Array of subtitle cues
 * @param currentTime - Current playback time in seconds
 * @returns The cue at the current time, or null if none found
 */
export function getCueAtTime(cues: SubtitleCue[], currentTime: number): SubtitleCue | null {
  return cues.find(cue =>
    currentTime >= cue.startTime && currentTime <= cue.endTime
  ) || null;
}

/**
 * Find the index of the cue at a specific time
 * @param cues - Array of subtitle cues
 * @param currentTime - Current playback time in seconds
 * @returns The index of the cue, or -1 if none found
 */
export function getCueIndexAtTime(cues: SubtitleCue[], currentTime: number): number {
  return cues.findIndex(cue =>
    currentTime >= cue.startTime && currentTime <= cue.endTime
  );
}

/**
 * Get the next subtitle cue after the current time
 * @param cues - Array of subtitle cues
 * @param currentTime - Current playback time in seconds
 * @returns The next cue, or null if at the end
 */
export function getNextCue(cues: SubtitleCue[], currentTime: number): SubtitleCue | null {
  return cues.find(cue => cue.startTime > currentTime) || null;
}

/**
 * Get the previous subtitle cue before the current time
 * @param cues - Array of subtitle cues
 * @param currentTime - Current playback time in seconds
 * @returns The previous cue, or null if at the beginning
 */
export function getPreviousCue(cues: SubtitleCue[], currentTime: number): SubtitleCue | null {
  // Find current cue index
  const currentIndex = getCueIndexAtTime(cues, currentTime);

  if (currentIndex > 0) {
    // Return the previous cue
    return cues[currentIndex - 1];
  } else if (currentIndex === -1 && cues.length > 0) {
    // Not currently in a cue, find the last cue before current time
    for (let i = cues.length - 1; i >= 0; i--) {
      if (cues[i].endTime < currentTime) {
        return cues[i];
      }
    }
  }

  return null;
}
