import { ChildCollection, VideoDetails } from "@/domain/Messages";
import { Player } from "@/services/Player";
import { Flex, Text } from "@mantine/core";
import { FC, useState } from "react";
import { CollectionCard } from "./CollectionCard";
import { fetchSeriesDetails, setCurrentSeason } from "@/domain/Store/SeriesReducer";
import { AppDispatch, RootState } from "@/domain/Store";
import { useDispatch, useSelector } from "react-redux";
import { getCollectionsAndVideos } from "@/domain/Utils";
import { VideoCard } from "./VideoCard";

interface IVideoGridProps {
  videoPlayer: Player;
}

export const VideoGrid: FC<IVideoGridProps> = ({ videoPlayer }) => {
  const [dialog, setDialog] = useState<JSX.Element>((<></>));
  const dispatch: AppDispatch = useDispatch();
  const activeSeries = useSelector((state: RootState) => state.series.activeSeries);
  const currentSeason = useSelector((state: RootState) => state.series.currentSeason);

  if (!activeSeries) {
    return <Text>Nothing to watch - download some videos</Text>;
  }

  const { child_collections, videos } = getCollectionsAndVideos(activeSeries, currentSeason);

  const onCollectionClick = (item: string) => {
    if (activeSeries.collection === "") {
      dispatch(fetchSeriesDetails(item));
    } else {
      dispatch(setCurrentSeason(item));
    }
  }

  const collection_items = child_collections.map((childCollection: ChildCollection): JSX.Element => {
    return (
      <CollectionCard
        key={`collection-${childCollection.collection}`}
        collection={childCollection}
        onClick={onCollectionClick}
      />
    );
  });

  const video_items = videos.map((video: VideoDetails, index: number): JSX.Element | null => {
    return (
      <VideoCard
        key={index}
        setDialog={setDialog}
        back={() => setDialog((<></>))}
        player={videoPlayer}
        video={video}
      />
    );
  });

  return (
    <>
      <Flex
        gap="md"
        bg="transparent"
        justify="center"
        align="flex-start"
        direction="row"
        wrap="wrap"
      >
        {collection_items}
        {video_items}
        {dialog}
      </Flex>
    </>
  );
}

