import { AppDispatch, RootState } from "@/domain/Store";
import { setCurrentSeason, fetchSeriesDetails } from "@/domain/Store/SeriesReducer";
import { Button } from "@mantine/core";
import { IconArrowLeft } from "@tabler/icons-react";
import { FC } from "react";
import { useDispatch, useSelector } from "react-redux";

interface IBackButton {
  size?: "xs" | "sm" | "md" | "lg" | "xl";
}

export const BackButton: FC<IBackButton> = ({ size = "md" }) => {
  const dispatch: AppDispatch = useDispatch();
  const seriesState = useSelector((state: RootState) => state.series);
  const activeSeries = seriesState.activeSeries;
  const currentSeason = seriesState.currentSeason;
  
  if (!activeSeries?.collection) {
    return null;
  }

  const onClick = () => {
    if (typeof currentSeason !== "undefined") {
      dispatch(setCurrentSeason(undefined));
      dispatch(fetchSeriesDetails(activeSeries.collection));
    } else {
      dispatch(fetchSeriesDetails(""));
    }
  }

  const iconSize = size === "xs" ? "1.5em" : size === "sm" ? "2em" : size === "lg" ? "2.5em" : size === "xl" ? "3em" : "2.5em";

  return <Button
    size={size}
    leftIcon={<IconArrowLeft size={iconSize} />}
    onClick={onClick}
  >
    Back
  </Button>;
}

