/**
 * React Component that renders the control bar for the player.
 * @param {ControlBarProps} props - The props object for the ControlBar component.
 * @returns {JSX.Element} - Returns the JSX element for the ControlBar component.
 */
import React, { FC, useState } from "react";
import {Player} from "../services/Player";
import { Button, Group, Stack} from "@mantine/core";
import { VideoDetails, RemotePlayerState } from "@/domain/Messages";
import { IconArrowLeftCircle, IconArrowRightCircle, IconPlayerPause, IconPlayerPlay, IconChevronLeft, IconChevronRight } from "@tabler/icons-react";

type ControlBarProps = {
  player: Player;
  video: VideoDetails;
  isCurrentlyPlaying: boolean;
  isPaused?: boolean;
  playerState?: RemotePlayerState;
  showSubtitleControls?: boolean;
}

const SIZE_ICON = "1.5em";

export const ControlBar:FC<ControlBarProps> = ({
  player,
  video,
  isCurrentlyPlaying,
  isPaused,
  playerState,
  showSubtitleControls = false
}) => {

  // If no video is loaded, show just a play button
  if (!isCurrentlyPlaying && typeof isPaused === "undefined") {
    return (
      <Group position="center">
        <ControlButton onClick={() => player.playVideo(video)}>
          <IconPlayerPlay size={SIZE_ICON}/>
        </ControlButton>
      </Group>
    );
  }

  // If a video is loaded (playing or paused), show full controls
  const playPauseIcon = isPaused ? <IconPlayerPlay size={SIZE_ICON}/> : <IconPlayerPause size={SIZE_ICON}/>;

  const hasSubtitles = playerState?.availableSubtitleTracks &&
                       playerState.availableSubtitleTracks.length > 0;
  const subtitlesEnabled = playerState?.currentSubtitleTrack !== null &&
                          playerState?.currentSubtitleTrack !== undefined;

  return (
    <Stack spacing="sm">
      {/* Main playback controls */}
      <Group position="center">
        <Group spacing="xs" grow>
          <ControlButton onClick={() => player.seek(-15)}>
            <IconArrowLeftCircle size={SIZE_ICON}/>
          </ControlButton>
          <ControlButton onClick={() => player.togglePause()}>
            {playPauseIcon}
          </ControlButton>
          <ControlButton onClick={() => player.seek(15)}>
            <IconArrowRightCircle size={SIZE_ICON}/>
          </ControlButton>
        </Group>
      </Group>

      {/* Subtitle navigation controls (if enabled and subtitles are active) */}
      {showSubtitleControls && hasSubtitles && subtitlesEnabled && (
        <Group position="center">
          <Group spacing="xs">
            <ControlButton onClick={() => player.seekToSubtitle('previous')}>
              <IconChevronLeft size={SIZE_ICON}/>
            </ControlButton>
            <ControlButton onClick={() => player.seekToSubtitle('next')}>
              <IconChevronRight size={SIZE_ICON}/>
            </ControlButton>
          </Group>
        </Group>
      )}
    </Stack>
  );
}

type ControlButtonProps = {
  children?: React.ReactNode;
  ariaLabel?: string;
  onClick: () => void;
}

/**
 * React component that renders a control button to be used in the ControlBar.
 * @param {ControlButtonProps} props - The props object for the ControlButton component.
 * @returns {JSX.Element} - Returns the JSX element for the ControlButton component.
 */
export const ControlButton = (props: ControlButtonProps) => {
  //const icon = React.createElement(props.iconClass, {color: "gray", size="1em"});
  /**
   * Handles the click event on the ControlButton component.
   * @returns {void} - Returns nothing.
   */
  const handleClick = (): void => {
    props.onClick();
  };
  return (
    <Button size="sm" variant="filled" onClick={() => handleClick()}>
      {props.children}
    </Button>
  )
}