import { Tabs } from '@mantine/core';
import { SearchTab } from './SearchTab';
import { Download } from './Download';
import { RestAdaptor } from '@/adaptors';

type SearchProps = {
  host: RestAdaptor
}

/**
 * The Search component renders a tabbed interface with search and download functionality
 */
export const Search: React.FC<SearchProps> = ({ host }) => {
  return (
    <Tabs defaultValue="search">
      <Tabs.List>
        <Tabs.Tab value="search">Search</Tabs.Tab>
        <Tabs.Tab value="download">Download</Tabs.Tab>
      </Tabs.List>

      <Tabs.Panel value="search" pt="xs">
        <SearchTab host={host} />
      </Tabs.Panel>

      <Tabs.Panel value="download" pt="xs">
        <Download host={host} />
      </Tabs.Panel>
    </Tabs>
  );
} 