import { Player } from "@/services/Player";
import { Menu, Burger, Text, createStyles } from "@mantine/core";
import { IconMessageCircle, IconPhoto, IconShare, IconSearch, IconInfoCircle } from "@tabler/icons-react";
import { Dispatch, SetStateAction, FC } from "react";
import { ConvertModal, VideoMetadataModal } from "./Modals";
import { VideoWrapper } from "@/domain/VideoWrapper";

// Create styles using Mantine's createStyles
const useStyles = createStyles(() => ({
  burgerIcon: {
    position: 'absolute',
    right: "1em",
    bottom: "1em",
    marginLeft: '1em'
  }
}));

interface IVideoMenu {
  player: Player;
  setDialog: Dispatch<SetStateAction<JSX.Element>>;
  back: (() => void);
  helper: VideoWrapper;
}

const HIDE_DIALOG = (<></>);

export const VideoMenu: FC<IVideoMenu> = ({player, setDialog, back, helper}) => {
  const { classes } = useStyles();

  const showConvertModal = (event: React.SyntheticEvent) => {
    event.stopPropagation();
    if (!helper.getId()) {
      return;
    }

    const onClose = () => setDialog(HIDE_DIALOG);

    const convertModal = (
      <ConvertModal onClose={onClose} videoId={helper.getId()} video={helper.name()} player={player} />
    );

    setDialog(convertModal);
  }

  const deleteVideo = (event: React.SyntheticEvent) => {
    event.stopPropagation();
    player.deleteVideo(helper.name(), helper.getId(), back);
  }

  const downloadVideo = (event: React.SyntheticEvent): void => {
    event.stopPropagation();

    if (helper.getId()) {
      // Create a new link
      const anchor = document.createElement('a');

      anchor.download = helper.name();
      anchor.href = helper.getUrl();

      // Append to the DOM
      document.body.appendChild(anchor);

      // Trigger `click` event
      anchor.click();

      // Remove element from DOM
      document.body.removeChild(anchor);
    }
  }

  const shareVideo = (event: React.SyntheticEvent): void => {
    event.stopPropagation();
    const id = helper.getId();
    if (id) {
      player.shareVideo(helper.name(), id);
    }
  }

  const showMetadataModal = (event: React.SyntheticEvent) => {
    event.stopPropagation();
    if (!helper.getId()) {
      return;
    }

    const video = helper.getVideo();
    if (!video || !video.metadata) {
      return;
    }

    const onClose = () => setDialog(HIDE_DIALOG);

    const metadataModal = (
      <VideoMetadataModal 
        onClose={onClose} 
        video={helper.name()} 
        metadata={video.metadata} 
      />
    );

    setDialog(metadataModal);
  }

  return (
    <Menu shadow="md" width={200} position="bottom-end" withArrow withinPortal>
      <Menu.Target>
        <Burger opened={false} className={classes.burgerIcon} />
      </Menu.Target>

      <Menu.Dropdown>
        <Menu.Item onClick={(event) => showMetadataModal(event)} icon={<IconInfoCircle size={14} />}>Video Info</Menu.Item>
        <Menu.Divider />
        <Menu.Item onClick={(event) => showConvertModal(event)} icon={<IconMessageCircle size={14} />}>Convert</Menu.Item>
        <Menu.Item onClick={(event) => downloadVideo(event)} icon={<IconPhoto size={14} />}>Download</Menu.Item>
        <Menu.Item onClick={(event) => shareVideo(event)} icon={<IconShare size={14} />}>Share</Menu.Item>
        <Menu.Divider />
        <Menu.Item
          onClick={(event) => deleteVideo(event)}
          icon={<IconSearch size={14} />}
          rightSection={<Text size="xs" color="dimmed">⌘K</Text>}
        >
          Delete
        </Menu.Item>
      </Menu.Dropdown>
    </Menu>
  );
}
