import React, { FC } from 'react';
import { Menu, Button, Text, Slider, Stack } from '@mantine/core';
import { 
  IconDashboardFilled, 
  IconTextCaption,
  IconLanguage,
  IconChevronDown,
  IconLetterT
} from '@tabler/icons-react';
import { AudioTrack, SubtitleTrack } from '@/domain/Messages';
import { BUTTON_SX, SIZE_ICON } from '@/domain/Constants';

interface PlaybackSpeedControlProps {
  currentRate: number;
  onRateChange: (rate: number) => void;
}

const MENU_WIDTH = 450;
const MENU_SX = {fontSize: '1.25rem'};
const MENU_LABEL_SX = {fontSize: '1.75rem', fontWeight: 700 as const};
const BUTTON_SIZE = 35;
const BUTTON_STYLE = { color: 'white', fontSize: '1.5rem', ...BUTTON_SX };

export const PlaybackSpeedControl: FC<PlaybackSpeedControlProps> = ({ currentRate, onRateChange }) => {
  const presetSpeeds = [0.5, 0.6, 0.7, 0.8, 0.9, 1];
  
  return (
    <Menu shadow="md" width={MENU_WIDTH}>
      <Menu.Target>
        <Button 
          rightIcon={<IconChevronDown size={BUTTON_SIZE} />}
          sx={BUTTON_STYLE}
        >
          <IconDashboardFilled size={SIZE_ICON} />
          <Text ml="xl">{currentRate}x</Text>
        </Button>
      </Menu.Target>

      <Menu.Dropdown>
        <Menu.Label sx={MENU_LABEL_SX}>Playback Speed</Menu.Label>
        <Stack p="xl">
          <Slider
            value={currentRate}
            onChange={onRateChange}
            min={0.5}
            max={1}
            step={0.1}
            marks={presetSpeeds.map(speed => ({ value: speed, label: `${speed}x` }))}
          />
        </Stack>
        <Menu.Divider />
        {presetSpeeds.map(speed => (
          <Menu.Item 
            key={speed} 
            onClick={() => onRateChange(speed)}
            sx={{ fontWeight: currentRate === speed ? 'bold' : 'normal', ...MENU_SX }}
          >
            {speed}x {speed === 1 && '(Normal)'}
          </Menu.Item>
        ))}
      </Menu.Dropdown>
    </Menu>
  );
};

interface AudioTrackSelectorProps {
  tracks: AudioTrack[];
  currentTrackId: number;
  onTrackChange: (trackId: number) => void;
}

export const AudioTrackSelector: FC<AudioTrackSelectorProps> = ({ tracks, currentTrackId, onTrackChange }) => {
  if (tracks.length <= 1) return null;

  return (
    <Menu shadow="md" width={MENU_WIDTH}>
      <Menu.Target>
        <Button 
          variant="subtle" 
          rightIcon={<IconChevronDown size={BUTTON_SIZE} />}
          sx={BUTTON_STYLE}
        >
          <IconLanguage size={SIZE_ICON} />
          <Text ml="xL">Audio</Text>
        </Button>
      </Menu.Target>

      <Menu.Dropdown>
        <Menu.Label sx={MENU_LABEL_SX}>Audio Track</Menu.Label>
        {tracks.map(track => (
          <Menu.Item 
            key={track.id} 
            onClick={() => onTrackChange(track.id)}
            sx={{ fontWeight: currentTrackId === track.id ? 'bold' : 'normal', ...MENU_SX }}
          >
            {track.label} {track.language && `(${track.language})`}
          </Menu.Item>
        ))}
      </Menu.Dropdown>
    </Menu>
  );
};

interface SubtitleSelectorProps {
  tracks: SubtitleTrack[];
  currentTrackId: number | null;
  onTrackChange: (trackId: number | null) => void;
}

export const SubtitleSelector: FC<SubtitleSelectorProps> = ({ tracks, currentTrackId, onTrackChange }) => {
  return (
    <Menu shadow="md" width={MENU_WIDTH}>
      <Menu.Target>
        <Button 
          variant="subtle" 
          rightIcon={<IconChevronDown size={BUTTON_SIZE} />}
          sx={BUTTON_STYLE}
        >
          <IconTextCaption size={SIZE_ICON} />
          <Text ml="xl">Subtitles</Text>
        </Button>
      </Menu.Target>

      <Menu.Dropdown>
        <Menu.Label sx={MENU_LABEL_SX}>Subtitles</Menu.Label>
        <Menu.Item 
          onClick={() => onTrackChange(null)}
          sx={{ fontWeight: currentTrackId === null ? 'bold' : 'normal', ...MENU_SX }}
        >
          Off
        </Menu.Item>
        <Menu.Divider />
        {tracks.map(track => (
          <Menu.Item 
            key={track.id} 
            onClick={() => onTrackChange(track.id)}
            sx={{ fontWeight: currentTrackId === track.id ? 'bold' : 'normal', ...MENU_SX }}
          >
            {track.label} {track.language && `(${track.language})`}
          </Menu.Item>
        ))}
      </Menu.Dropdown>
    </Menu>
  );
}; 

interface SubtitleFontSizeControlProps {
  fontSizePx: number;
  onChange: (sizePx: number) => void;
}

export const SubtitleFontSizeControl: FC<SubtitleFontSizeControlProps> = ({ fontSizePx, onChange }) => {
  const min = 24;
  const max = 72;
  const step = 12;
  const marks = [24, 48, 72].map(v => ({ value: v, label: `${v}px` }));

  return (
    <Menu shadow="md" width={MENU_WIDTH}>
      <Menu.Target>
        <Button 
          variant="subtle" 
          rightIcon={<IconChevronDown size={BUTTON_SIZE} />}
          sx={BUTTON_STYLE}
        >
          <IconLetterT size={SIZE_ICON} />
          <Text ml="xl">{fontSizePx}px</Text>
        </Button>
      </Menu.Target>

      <Menu.Dropdown>
        <Menu.Label sx={MENU_LABEL_SX}>Subtitle Size</Menu.Label>
        <Stack p="xl">
          <Slider
            value={fontSizePx}
            onChange={onChange}
            min={min}
            max={max}
            step={step}
            marks={marks}
          />
        </Stack>
      </Menu.Dropdown>
    </Menu>
  );
}; 