import { ChildCollection } from "@/domain/Messages";
import { Card, Image, Text, useMantineTheme } from "@mantine/core";
import { FC } from "react";
import { getCardSizes, getThumbnail } from "@/domain/Utils";
import { useMediaQuery } from "@mantine/hooks";


interface ICollectionCardProps {
  collection: ChildCollection;
  onClick: (collection: string) => void;
}

/**
* CollectionCard component, used to display each collection item
* 
* @param {ICollectionCardProps} props - object containing the attributes of the collection item to be displayed
* 
* @returns {JSX.Element} - returns a JSX element containing the collection item to be displayed
*/
export const CollectionCard: FC<ICollectionCardProps> = ({ collection, onClick }) => {
  const theme = useMantineTheme();
  const useSmallImages = useMediaQuery(`(max-width: ${theme.breakpoints.xl})`);
  const dimensions = getCardSizes(useSmallImages);
  const displayName = collection.collection ? collection.collection : "Others";

  return (
    <Card onClick={() => onClick(collection.collection)} w={dimensions.imgWidth} radius="md">
      <Card.Section>
        <Image
          width={dimensions.imgWidth}
          height={dimensions.imgHeight}
          radius="md"
          src={getThumbnail(collection.thumbnail, dimensions.imgWidth)}
          alt={`image from ${collection.collection}`}
        />
      </Card.Section>
      <Card.Section p={16} h={dimensions.footerHeight}>
        <Text fz="xl">{displayName}</Text>
      </Card.Section>
    </Card>
  );
}
