import { RootState, AppDispatch } from "@/domain/Store";
import { useSelector, useDispatch } from "react-redux";
import { Autocomplete, Stack } from "@mantine/core";
import { setAddToSeries } from "@/domain/Store/SearchReducer";

const DownloadConfirm = () => {
  const addToSeries = useSelector((state: RootState) => state.search.addToSeries);
  const allSeries = useSelector((state: RootState) => state.series.allSeries);
  const dispatch: AppDispatch = useDispatch();

  const seriesNames = allSeries?.map((series) => series.collection) || [];

  const updateAddToSeries = (value: string) => {
    dispatch(setAddToSeries(value));
  }

  return (
    <Stack>
      <Autocomplete
        label="Set location for download"
        value={addToSeries}
        onChange={updateAddToSeries}
        data={seriesNames}
        placeholder="Add to series"
        withinPortal={true}
      />
    </Stack>
  )
}

export default DownloadConfirm;