import { Player } from "../../services/Player";
import {Image, Stack, Text, Card, RingProgress, Grid, useMantineTheme, createStyles, Tabs, Box } from "@mantine/core";
import React, {Dispatch, FC, SetStateAction, useState, useRef, useEffect} from "react";
import { VideoDetails, SubtitleCue} from "../../domain/Messages";
import {ControlBar} from "../ControlBar";
import { getCardSizes, getThumbnail, getThumbnailFromName } from "@/domain/Utils";
import { useMediaQuery } from "@mantine/hooks";
import { VideoMenu } from "./VideoMenu";
import { VideoWrapper } from "@/domain/VideoWrapper";
import { SubtitleDisplay } from "./SubtitleDisplay";
import { SubtitleNavigator } from "./SubtitleNavigator";
import { IconInfoCircle, IconTextCaption } from "@tabler/icons-react";

// Create styles using Mantine's createStyles
const useStyles = createStyles((theme) => ({
  title: {
    fontWeight: 500,
    fontSize: theme.fontSizes.lg
  }
}));

interface VideoDetailDialogProps {
  helper: VideoWrapper;
  player: Player;
  description: JSX.Element;
  setDialog: Dispatch<SetStateAction<JSX.Element>>;
  back: (() => void);
}

export const VideoItemDialogDetail: FC<VideoDetailDialogProps> = ({helper, player, description, setDialog, back}) => {
  const { classes } = useStyles();
  const theme = useMantineTheme();
  const useSmallImages = useMediaQuery(`(max-width: ${theme.breakpoints.lg})`);
  const dimensions = getCardSizes(useSmallImages);
  const video = helper.getVideo();
  const [showSubtitleControls, setShowSubtitleControls] = useState(true);
  const [referenceTrackId, setReferenceTrackId] = useState<number | null>(null);
  const playerState = helper.getLastPlayerState();
  const detailsPanelRef = useRef<HTMLDivElement>(null);
  const [panelHeight, setPanelHeight] = useState<number | undefined>(undefined);
  const [scrollMode, setScrollMode] = useState<'follow' | 'scroll'>('scroll');
  const [scrollIndex, setScrollIndex] = useState<number>(0);
  const [scrollCues, setScrollCues] = useState<SubtitleCue[]>([]);

  // Measure the Details panel height once it's rendered
  useEffect(() => {
    if (detailsPanelRef.current) {
      const height = detailsPanelRef.current.offsetHeight;
      setPanelHeight(height);
    }
  }, [video]);

  const thumbnail = video?.thumbnail ? getThumbnail(video.thumbnail, dimensions.imgWidth) : getThumbnailFromName(helper.name(), dimensions.imgWidth);

  const image = <Image
      maw={dimensions.imgWidth}
      mx="auto" 
      radius="md" 
      fit="contain"
      src={thumbnail}
      alt={`image from ${helper.name()}`}
      sx={{ cursor: 'pointer' }}
    />;

  const playPercentage = helper.getPercentPlayed();
  const ringColour = playPercentage === 100 ? 'green' : 'blue';
  const ringProgress = playPercentage == 0 ? null : <RingProgress
    sx={{zIndex: 100, position: "absolute", top: "10", left: "10"}}
    sections={[
      {value: playPercentage, color: ringColour }, 
    ]}
    size={84}
    label={
      <Text color={ringColour} weight={500} align="center" size="sm">
        {playPercentage}%
      </Text>
    }
  />;

  const hasSubtitles = video?.metadata?.subtitleTracks &&
                       video.metadata.subtitleTracks.length > 0;

  const card = (
    <Stack sx={{ width: dimensions.imgWidth, maxWidth: '100%' }}>
      {/* Tabs for Details and Subtitles */}
      <Tabs defaultValue="details">
        <Tabs.List>
          <Tabs.Tab value="details" icon={<IconInfoCircle size="0.8rem" />}>
            Details
          </Tabs.Tab>
          {hasSubtitles && (
            <Tabs.Tab value="subtitles" icon={<IconTextCaption size="0.8rem" />}>
              Subtitles
            </Tabs.Tab>
          )}
        </Tabs.List>

        <Tabs.Panel value="details" pt="xs">
          <Box ref={detailsPanelRef}>
            <Stack>
              <Card shadow="sm" padding="lg" radius="md" withBorder>
                <Card.Section onClick={() => playVideo(player, video)}>
                  { ringProgress }
                  { image }
                </Card.Section>
                <Card.Section>
                  <Grid>
                    <Grid.Col span={12} className={classes.title}>
                      <div>
                        <Text size="lg" sx={{ cursor: 'pointer' }} onClick={() => playVideo(player, video)}>{helper.displayName()}</Text>
                        <VideoMenu setDialog={setDialog} back={back} player={player} helper={helper} />
                      </div>
                    </Grid.Col>
                    <Grid.Col span={12}>{description}</Grid.Col>
                  </Grid>
                </Card.Section>
              </Card>
              <ControlBar
                player={player}
                video={video}
                isCurrentlyPlaying={helper.isCurrentlyPlaying()}
                isPaused={playerState?.paused}
                playerState={playerState}
                showSubtitleControls={false}
              />
            </Stack>
          </Box>
        </Tabs.Panel>

        {hasSubtitles && (
          <Tabs.Panel value="subtitles" pt="xs">
            <Stack spacing="md" sx={{ height: panelHeight ? `${panelHeight}px` : 'auto' }}>
              <SubtitleDisplay
                playerState={playerState}
                availableSubtitleTracks={video.metadata?.subtitleTracks}
                currentSubtitleTrack={playerState?.currentSubtitleTrack ?? 0}
                showReference={referenceTrackId !== null}
                referenceTrackId={referenceTrackId}
                videoUrl={video?.url}
                scrollMode={scrollMode}
                scrollIndex={scrollIndex}
                scrollCues={scrollCues}
              />
              <SubtitleNavigator
                player={player}
                playerState={playerState}
                availableSubtitleTracks={video.metadata?.subtitleTracks}
                currentSubtitleTrack={playerState?.currentSubtitleTrack ?? 0}
                showReferenceSelector={true}
                currentReferenceTrack={referenceTrackId}
                onReferenceTrackChange={setReferenceTrackId}
                videoUrl={video?.url}
                onScrollModeChange={(mode, index, cues) => {
                  setScrollMode(mode);
                  setScrollIndex(index);
                  setScrollCues(cues);
                }}
              />
            </Stack>
          </Tabs.Panel>
        )}
      </Tabs>
    </Stack>
  );

  return card;
}

/**
 * A function that plays the video.
 * @param player - The player instance
 * @param video - The video details
 */
const playVideo = (player: Player, video?: VideoDetails): void => {
  if (typeof video !== "undefined") {
    player.playVideo(video);
  }
}
