import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { SearchResult } from "../Messages";
import { SE_PIRATEBAY } from '../Constants';

export interface SearchState {
  term: string;
  engine: string,
  results: SearchResult[],
  lastSearch: string,
  addToSeries: string
};

const initialState: SearchState = {
  term: '',
  engine: SE_PIRATEBAY,
  results: [],
  lastSearch: '',
  addToSeries: ''
};

export const searchSlice = createSlice({
  name: 'search',
  initialState,
  reducers: {
    setTerm: (state, action: PayloadAction<string>) => {
      state.term = action.payload;
    },
    setEngine: (state, action: PayloadAction<string>) => {
      state.engine = action.payload;
    },
    setResults: (state, action: PayloadAction<SearchResult[]>) => {
      state.results = action.payload;
    },
    setLastSearch: (state, action: PayloadAction<string>) => {
      state.lastSearch = action.payload;
    },
    setAddToSeries: (state, action: PayloadAction<string>) => {
      state.addToSeries = action.payload;
    }
  }
});

export const { setTerm, setEngine, setResults, setLastSearch, setAddToSeries } = searchSlice.actions;

export default searchSlice.reducer;
