import React, { useImperativeHandle, useEffect, forwardRef, useRef, ForwardedRef, useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { AudioTrack, PlayRequest, SubtitleTrack } from '@/domain/Messages';
import { socketSend } from '@/domain/Store/SocketMiddleware';
import { RootState } from '@/domain/Store';
import { clearSeekEvent } from '@/domain/Store/VideoReducer';
import { log_info, log_warning } from "@/services/Logger";
import { convertFileSrc } from "@tauri-apps/api/core";
import { isTauri } from "@/utils/browserCompat";

export enum PlayState {
  STOPPED = 1,
  PAUSED,
  STARTED,
  ERROR
}

export interface PlayerHandlers {
  pause: () => void;
  seek: (interval: number) => void;
  isPlaying: () => boolean;
  setPlaybackRate: (rate: number) => void;
  setAudioTrack: (trackId: number) => void;
  setSubtitleTrack: (trackId: number | null) => void;
  getAvailableAudioTracks: () => AudioTrack[];
  getAvailableSubtitleTracks: () => SubtitleTrack[];
  setSubtitleFontSize: (sizePx: number) => void;
  getSubtitleFontSize: () => number;
}

export interface PlayerProps {
  currentVideo: PlayRequest;
  onStateChange: (state: PlayState) => void;
}

// Local extension: allow metadata on PlayRequest for subtitle tracks
type PlayRequestWithMetadata = PlayRequest & { metadata?: { subtitleTracks?: SubtitleTrack[] } };

const Player = forwardRef((props: PlayerProps, ref: ForwardedRef<PlayerHandlers>) => {
  const dispatch = useDispatch();
  const videoRef = useRef<HTMLVideoElement>(null);
  const counter = useRef(0);
  const [currentSubtitleTrack, setCurrentSubtitleTrack] = useState<number | null>(null);
  
  // Subtitle font sizing support
  const subtitleStyleRef = useRef<HTMLStyleElement | null>(null);
  const subtitleFontPxRef = useRef<number>(24);
  const ensureSubtitleStyle = () => {
    if (!subtitleStyleRef.current) {
      const el = document.createElement('style');
      el.setAttribute('data-subtitle-style', 'true');
      document.head.appendChild(el);
      subtitleStyleRef.current = el;
    }
  };
  const updateSubtitleStyle = () => {
    ensureSubtitleStyle();
    const id = props.currentVideo.videoId.replace(/"/g, '\\"');
    const px = subtitleFontPxRef.current;
    if (subtitleStyleRef.current) {
      subtitleStyleRef.current.textContent = `video[data-player-id="${id}"]::cue { font-size: ${px}px; }`;
    }
  };
  useEffect(() => {
    updateSubtitleStyle();
    return () => {
      if (subtitleStyleRef.current) {
        subtitleStyleRef.current.textContent = '';
      }
    };
  }, [props.currentVideo.videoId]);
  
  // Listen for seek events from Redux
  const seekEvent = useSelector((state: RootState) => state.video.seekEvent);

  // Define the handlers that will be exposed through the ref
  useImperativeHandle(ref, () => ({
    pause: () => {
      if (videoRef.current) {
        if (videoRef.current.paused) {
          void videoRef.current.play();
          props.onStateChange(PlayState.STARTED);
        } else {
          videoRef.current.pause();
          props.onStateChange(PlayState.PAUSED);
        }
      }
    },
    seek: (interval: number) => {
      if (videoRef.current) {
        videoRef.current.currentTime += interval;
      }
    },
    isPlaying: () => {
      return videoRef.current ? !videoRef.current.paused : false;
    },
    setPlaybackRate: (rate: number) => {
      if (videoRef.current) {
        videoRef.current.playbackRate = rate;
        dispatch(socketSend({ SetPlaybackRate: { rate } }));
      }
    },
    setAudioTrack: (trackId: number) => {
      type Track = { enabled: boolean; language?: string; label?: string };
      type V = HTMLVideoElement & { audioTracks?: { length: number; [index: number]: Track } };
      const v = videoRef.current as V | null;
      if (v && v.audioTracks) {
        const audioTracks: Track[] = Array.from({ length: v.audioTracks.length }, (_, i) => v.audioTracks![i]);
        audioTracks.forEach((track: Track, index: number) => {
          track.enabled = index === trackId;
        });
        dispatch(socketSend({ SetAudioTrack: { trackId } }));
      }
    },
    setSubtitleTrack: (trackId: number | null) => {
      if (videoRef.current && videoRef.current.textTracks) {
        const textTracks = Array.from(videoRef.current.textTracks);
        textTracks.forEach((track, index) => {
          track.mode = index === trackId ? 'showing' : 'hidden';
        });
        setCurrentSubtitleTrack(trackId);
        dispatch(socketSend({ SetSubtitleTrack: { trackId } }));
      }
    },
    getAvailableAudioTracks: () => {
      type Track = { enabled: boolean; language?: string; label?: string };
      type V = HTMLVideoElement & { audioTracks?: { length: number; [index: number]: Track } };
      const v = videoRef.current as V | null;
      if (v && v.audioTracks) {
        const audioTracks: Track[] = Array.from({ length: v.audioTracks.length }, (_, i) => v.audioTracks![i]);
        return audioTracks.map((track: Track, index: number) => ({
          id: index,
          language: track.language || 'Unknown',
          label: track.label || `Track ${index + 1}`,
          default: !!track.enabled
        }));
      }
      return [];
    },
    getAvailableSubtitleTracks: () => {
      if (videoRef.current && videoRef.current.textTracks) {
        const list = Array.from(videoRef.current.textTracks);
        if (list.length > 0) {
          return list.map((track, index) => ({
            id: index,
            language: track.language || 'Unknown',
            label: track.label || `Subtitle ${index + 1}`,
            format: track.kind,
            default: track.mode === 'showing'
          }));
        }
      }
      const withMeta = props.currentVideo as PlayRequestWithMetadata;
      const subtitleTracks = withMeta.metadata?.subtitleTracks;
      if (subtitleTracks && subtitleTracks.length > 0) {
        return subtitleTracks.map((t, index) => ({
          id: index,
          language: t.language || 'Unknown',
          label: t.label || (t.language || `Subtitle ${index + 1}`),
          format: 'subtitles',
          default: !!t.default
        }));
      }
      return [];
    },
    setSubtitleFontSize: (sizePx: number) => {
      subtitleFontPxRef.current = sizePx;
      updateSubtitleStyle();
    },
    getSubtitleFontSize: () => subtitleFontPxRef.current,
  }));

  // Listen for Redux-managed seek events
  useEffect(() => {
    if (videoRef.current && seekEvent !== undefined) {
      videoRef.current.currentTime += seekEvent;
      dispatch(clearSeekEvent());
    }
  }, [seekEvent, dispatch]);

  // Listen for Redux-managed play/pause state
  const isPlayingFromRedux = useSelector((state: RootState) => state.video.isPlaying);
  useEffect(() => {
    if (videoRef.current) {
      if (isPlayingFromRedux && videoRef.current.paused) {
        void videoRef.current.play();
        props.onStateChange(PlayState.STARTED);
      } else if (!isPlayingFromRedux && !videoRef.current.paused) {
        videoRef.current.pause();
        props.onStateChange(PlayState.PAUSED);
      }
    }
  }, [isPlayingFromRedux, props]);

  // Set up subtitle tracks when video loads
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const handleLoadedMetadata = () => {
      Array.from(video.querySelectorAll('track[data-generated="true"][kind="subtitles"]')).forEach((el) => el.remove());
      const deriveVttUrl = (baseUrl: string, lang: string): string => {
        const LANG = (lang || '').toUpperCase();
        try {
          const [pathOnly] = baseUrl.split(/[?#]/, 1);
          const dot = pathOnly.lastIndexOf('.');
          const base = dot > -1 ? pathOnly.substring(0, dot) : pathOnly;
          return `${base}-${LANG}.vtt`;
        } catch {
          const dot = baseUrl.lastIndexOf('.');
          const base = dot > -1 ? baseUrl.substring(0, dot) : baseUrl;
          return `${base}-${LANG}.vtt`;
        }
      };

      const withMeta = props.currentVideo as PlayRequestWithMetadata;
      const subtitleTracks = withMeta.metadata?.subtitleTracks;
      if (subtitleTracks && subtitleTracks.length > 0) {
        subtitleTracks.forEach((track) => {
          const language = track.language || 'und';
          const src = track.url || deriveVttUrl(props.currentVideo.url, language);
          const trackElement = document.createElement('track');
          trackElement.setAttribute('data-generated', 'true');
          trackElement.kind = 'subtitles';
          trackElement.label = track.label || language;
          trackElement.srclang = language;
          trackElement.src = src;
          if (track.default) {
            trackElement.default = true;
          }
          video.appendChild(trackElement);
        });
      }

      updateSubtitleStyle();
    };

    if (video.readyState >= 1) {
      handleLoadedMetadata();
    } else {
      video.addEventListener('loadedmetadata', handleLoadedMetadata);
      video.addEventListener('loadeddata', handleLoadedMetadata);
    }
    return () => {
      video.removeEventListener('loadedmetadata', handleLoadedMetadata);
      video.removeEventListener('loadeddata', handleLoadedMetadata);
    };
  }, [props.currentVideo]);

  const getNextVideo = () => {
    log_info(`Video completed: ${props.currentVideo.video}`);
  };

  const logVideoError = () => {
    log_warning(`Error playing: ${props.currentVideo.video}`);
    props.onStateChange(PlayState.ERROR);
  };

  const getVideoUrl = () => {
    try {
      if (isTauri()) {
        return convertFileSrc(props.currentVideo.url);
      }
    } catch {
    }
    return props.currentVideo.url;
  };

  const sendPlayerState = (player: HTMLVideoElement) => {
    const playerState = {
      State: {
        collection: props.currentVideo.collection,
        video: props.currentVideo.video,
        videoId: props.currentVideo.videoId,
        currentTime: player.currentTime,
        duration: player.duration,
        paused: player.paused,
        playbackRate: player.playbackRate,
        currentSubtitleTrack,
      },
    };
    dispatch(socketSend(playerState));
  };

  const onTimeUpdate = (e: React.SyntheticEvent<HTMLVideoElement>) => {
    const player = e.currentTarget as HTMLVideoElement;

    if (counter.current % 3 === 0) {
      sendPlayerState(player);
    }
    counter.current++;
  };

  const onKeyPressed = (evt: React.KeyboardEvent<HTMLVideoElement>) => {
    switch (evt.key) {
      case " ":
        if (videoRef.current?.paused) {
          void videoRef.current.play();
          props.onStateChange(PlayState.STARTED);
        } else {
          videoRef.current?.pause();
          props.onStateChange(PlayState.PAUSED);
        }
        break;
    }
  };

  return (
    <video
      ref={videoRef}
      src={getVideoUrl()}
      style={{ width: '100%', height: '100%', objectFit: 'contain' }}
      controls
      autoPlay
      crossOrigin="anonymous"
      data-player-id={props.currentVideo.videoId}
      onPlay={(e) => {
        props.onStateChange(PlayState.STARTED);
        sendPlayerState(e.currentTarget);
      }}
      onPause={(e) => {
        props.onStateChange(PlayState.PAUSED);
        sendPlayerState(e.currentTarget);
      }}
      onEnded={() => {
        getNextVideo();
        props.onStateChange(PlayState.STOPPED);
      }}
      onError={() => logVideoError()}
      onTimeUpdate={(e) => onTimeUpdate(e)}
      onKeyDown={(e) => onKeyPressed(e)}
    />
  );
});

export default Player;
