/**
 * React Component that renders the control bar for the player.
 * @param {ControlsProps} props - The props object for the ControlBar component.
 * @returns {JSX.Element} - Returns the JSX element for the ControlBar component.
 */
import React, { FC, useEffect, useRef, useState } from "react";
import { Affix, Button, Group, rem } from "@mantine/core";
import { 
  IconArrowLeftCircle, 
  IconArrowRightCircle, 
  IconMaximize, 
  IconMinimize,
  IconDoorExit,
  IconPlayerPlay,
  IconPlayerPause
} from "@tabler/icons-react";
import { AnalogClock, remToPx } from '@/components/Widgets/AnalogClock';
import { PlaybackSpeedControl, AudioTrackSelector, SubtitleSelector, SubtitleFontSizeControl } from './MediaControls';
import { PlayerHandlers } from './Player';
import { SubtitleTrack } from "@/domain/Messages";
import { AudioTrack } from "@/domain/Messages";
import { BUTTON_COLOUR, BUTTON_SX, SIZE_ICON } from '@/domain/Constants';

type ControlsProps = {
  seek: (interval: number) => void;
  togglePause?: () => void;
  quit: () => void;
  isPlaying?: () => boolean;
  currentlyPlaying?: boolean;
  playerRef?: React.RefObject<PlayerHandlers>;
}

const CLOCK_SIZE = 12;
const HIDE_DELAY = 7000;
const DOUBLE_TAP_DELAY = 300; // milliseconds between taps to be considered a double tap

export const Controls: FC<ControlsProps> = ({ seek, togglePause, isPlaying, currentlyPlaying, quit, playerRef }) => {
  const [isFullScreen, setIsFullScreen] = useState<boolean>(false);
  const [isVisible, setIsVisible] = useState<boolean>(true);
  const [playbackRate, setPlaybackRate] = useState<number>(1);
  const [audioTracks, setAudioTracks] = useState<AudioTrack[]>([]);
  const [subtitleTracks, setSubtitleTracks] = useState<SubtitleTrack[]>([]);
  const [currentAudioTrack, setCurrentAudioTrack] = useState<number>(0);
  const [currentSubtitleTrack, setCurrentSubtitleTrack] = useState<number | null>(null);
  const [subtitleFontPx, setSubtitleFontPx] = useState<number>(24);
  const timeoutRef = useRef<number | null>(null);
  const lastTapTimeRef = useRef<number>(0);
  
  const hideControls = () => {
    setIsVisible(false);
  };

  const tryTogglePause = () => {
    if (typeof(togglePause) !== "undefined") {
      togglePause();
    }
  }

  const tryIsPlaying = () => {
    if (typeof(isPlaying) !== "undefined") {
      return isPlaying();
    }
    return false;
  }

  const leave = (e?: React.MouseEvent<HTMLButtonElement>) => {
    e?.stopPropagation();
    if (tryIsPlaying()) {
      tryTogglePause();
    }
    quit();
  }

  const showControls = () => {
    setIsVisible(true);
    
    // Reset the timeout
    if (timeoutRef.current !== null) {
      window.clearTimeout(timeoutRef.current);
    }
    
    // Set a new timeout to hide controls after HIDE_DELAY seconds
    timeoutRef.current = window.setTimeout(hideControls, HIDE_DELAY);
  };

  // Update track information when player is ready
  useEffect(() => {
    if (playerRef?.current) {
      const updateTracks = () => {
        const availableAudioTracks = playerRef.current?.getAvailableAudioTracks() || [];
        const availableSubtitleTracks = playerRef.current?.getAvailableSubtitleTracks() || [];
        setAudioTracks(availableAudioTracks);
        setSubtitleTracks(availableSubtitleTracks);
        const currentSize = playerRef.current?.getSubtitleFontSize?.();
        if (typeof currentSize === 'number' && !Number.isNaN(currentSize)) {
          setSubtitleFontPx(currentSize);
        }
      };

      // Update tracks after a short delay to ensure video metadata is loaded
      const timer = setTimeout(updateTracks, 1000);
      return () => clearTimeout(timer);
    }
  }, [playerRef, currentlyPlaying]);

  const handlePlaybackRateChange = (rate: number) => {
    setPlaybackRate(rate);
    playerRef?.current?.setPlaybackRate(rate);
  };

  const handleAudioTrackChange = (trackId: number) => {
    setCurrentAudioTrack(trackId);
    playerRef?.current?.setAudioTrack(trackId);
  };

  const handleSubtitleTrackChange = (trackId: number | null) => {
    setCurrentSubtitleTrack(trackId);
    playerRef?.current?.setSubtitleTrack(trackId);
  };

  const handleSubtitleFontSizeChange = (sizePx: number) => {
    setSubtitleFontPx(sizePx);
    playerRef?.current?.setSubtitleFontSize(sizePx);
  }
  
  // Handle double tap detection
  const handleTouchTap = (e: TouchEvent) => {
    const currentTime = new Date().getTime();
    const tapLength = currentTime - lastTapTimeRef.current;
    
    if (tapLength < DOUBLE_TAP_DELAY && tapLength > 0) {
      // Double tap detected
      e.preventDefault();
      tryTogglePause();
    }
    
    lastTapTimeRef.current = currentTime;
  };
  
  useEffect(() => {
    // Show controls initially with timeout
    showControls();
    
    // Set up event listeners for user interaction
    const handleUserInteraction = () => {
      showControls();
    };
    
    window.addEventListener('mousemove', handleUserInteraction);
    window.addEventListener('click', handleUserInteraction);
    window.addEventListener('keydown', handleUserInteraction);
    // Add touch event listeners
    window.addEventListener('touchstart', handleUserInteraction);
    window.addEventListener('touchmove', handleUserInteraction);
    
    // Add touch tap detection
    window.addEventListener('touchend', handleTouchTap);
    
    // Clean up
    return () => {
      if (timeoutRef.current !== null) {
        window.clearTimeout(timeoutRef.current);
      }
      window.removeEventListener('mousemove', handleUserInteraction);
      window.removeEventListener('click', handleUserInteraction);
      window.removeEventListener('keydown', handleUserInteraction);
      // Remove touch event listeners
      window.removeEventListener('touchstart', handleUserInteraction);
      window.removeEventListener('touchmove', handleUserInteraction);
      window.removeEventListener('touchend', handleTouchTap);
    };
  }, []);
  
  useEffect(() => {
    const handleFullScreenChange = () => {
      setIsFullScreen(!!document.fullscreenElement);
    };
    
    document.addEventListener('fullscreenchange', handleFullScreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullScreenChange);
  }, []);

  const toggleFullScreen = async () => {
    if (document.fullscreenElement) {
      await document.exitFullscreen();
    } else {
      await document.documentElement.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${JSON.stringify(err)}`);
      });
    }
  };

  const topButtons = (
    <Group spacing="xl" grow sx={{ opacity: 0.7 }}>
      <ControlButton onClick={() => seek(-30)}>
        <IconArrowLeftCircle size={SIZE_ICON} />
      </ControlButton>
      <ControlButton onClick={tryTogglePause}>
        {currentlyPlaying ? <IconPlayerPause size={SIZE_ICON} /> : <IconPlayerPlay size={SIZE_ICON} />}
      </ControlButton>
      <ControlButton onClick={() => void toggleFullScreen()}>
        {isFullScreen ? <IconMinimize size={SIZE_ICON} /> : <IconMaximize size={SIZE_ICON} />}
      </ControlButton>
      <ControlButton onClick={() => seek(30)}>
        <IconArrowRightCircle size={SIZE_ICON} />
      </ControlButton>
    </Group>
  )

  const leftButtons = (
    <Group spacing="xl" grow sx={{ opacity: 0.7 }}>
      <ControlButton onClick={(e) => leave(e)}>
        <IconDoorExit size={SIZE_ICON} />
      </ControlButton>
    </Group>
  )

  const clockSize = remToPx(CLOCK_SIZE);

  const rightButtons = (
    <Group spacing="xl" grow sx={{ opacity: 0.7 }}>
      <AnalogClock 
        size={clockSize} 
        dialColor={BUTTON_COLOUR}
        digitalTimeFormat="12h"
      />
    </Group>
  )

  // Bottom controls for media options
  const bottomButtons = (
    <Group spacing="xl" grow sx={{ opacity: 0.7 }}>
      <PlaybackSpeedControl 
        currentRate={playbackRate} 
        onRateChange={handlePlaybackRateChange} 
      />
      {audioTracks.length > 1 && (
        <AudioTrackSelector
          tracks={audioTracks}
          currentTrackId={currentAudioTrack}
          onTrackChange={handleAudioTrackChange}
        />
      )}
      {subtitleTracks.length > 0 && (
        <SubtitleSelector
          tracks={subtitleTracks}
          currentTrackId={currentSubtitleTrack}
          onTrackChange={handleSubtitleTrackChange}
        />
      )}
      {subtitleTracks.length > 0 && (
        <SubtitleFontSizeControl 
          fontSizePx={subtitleFontPx} 
          onChange={handleSubtitleFontSizeChange} />
      )}
    </Group>
  )

  if (!isVisible) {
    return null;
  }

  return (
    <>
      <Affix 
        key="top-video-controls" 
        position={{ top: rem(100), left: '50%' }}
        sx={{ transform: 'translateX(-50%)' }}
      >
        {topButtons}
      </Affix>
      <Affix 
        key="left-video-controls" 
        position={{ top: '50%', left: rem(100) }}
        sx={{ transform: 'translateY(-50%)' }}
      >
        {leftButtons}
      </Affix>
      <Affix 
        key="right-video-controls" 
        position={{ top: '50%', right: rem(100) }}
        sx={{ transform: 'translateY(-50%)' }}
      >
        {rightButtons}
      </Affix>
      <Affix
        key="bottom-video-controls"
        position={{ bottom: rem(50), left: '50%' }}
        sx={{ transform: 'translateX(-50%)' }}
      >
        {bottomButtons}
      </Affix>
    </>
  )
}

type ControlButtonProps = {
  children?: React.ReactNode;
  ariaLabel?: string;
  onClick: (e?: React.MouseEvent<HTMLButtonElement>) => void;
}

/**
 * React component that renders a control button to be used in the ControlBar.
 * @param {ControlButtonProps} props - The props object for the ControlButton component.
 * @returns {JSX.Element} - Returns the JSX element for the ControlButton component.
 */
export const ControlButton = (props: ControlButtonProps) => {
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>): void => {
    props.onClick(e);
  };
  return (
    <Button 
      size="xl" 
      variant="filled" 
      onClick={(e) => handleClick(e)}
      sx={BUTTON_SX}
    >
      {props.children}
    </Button>
  )
}
